// Ideeënbibliotheek van Groteknut (46 ideeën).
// Eén idee per regel. Controleer wijzigingen met: node tools/validate.mjs
export default [
  {"id":"marmerpapier-scheerschuim","title":"Marmerpapier met scheerschuim","emoji":"🌀","category":"verven","summary":"Druppel kleur op een laag schuim, trek er krullen door en druk je papier erop: elk vel wordt een uniek marmerkunstwerk.","ageMin":3,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"scheerschuim","note":"of zelfgemaakt zeepschuim"},{"id":"dienblad","note":"met een randje"},{"id":"kleurstof","note":"of plakkaatverf, 2-3 kleuren"},{"id":"karton","note":"of dik papier, iets kleiner dan het dienblad"},{"id":"ijsstokjes","note":"om mee te roeren én af te schrapen"}],"optional":[{"id":"pipet","note":"om druppels te maken"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Spuit een laag scheerschuim van een paar centimeter op het dienblad en strijk het glad met een ijsstokje.","Laat je kind druppels kleurstof of verf over het schuim verdelen.","Trek met een ijsstokje slingers en krullen door de kleuren. Niet te veel roeren, anders wordt het één kleur.","Druk een vel karton plat op het schuim en tel samen tot vijf.","Haal het karton eraf en schraap het schuim weg met een schoon ijsstokje: daar is je marmerpatroon!","Laat het vel drogen. Er is meestal schuim genoeg voor nog twee of drie afdrukken."],"ageTips":{"young":"Voor een driejarige is druppelen en roeren het leukste deel. Doe het afdrukken en afschrapen samen en laat het eindresultaat los.","old":"Kies samen passende kleuren (bijv. blauw en groen voor ‘zee’) en knip van het gedroogde marmerpapier vissen of een kaart."},"safety":["Scheerschuim is niet om te eten en prikt in de ogen: houd een doekje klaar en was handen meteen na afloop. Kies bij een gevoelige huid zeepschuim.","Kleurstof vlekt op kleding en tafel: trek een oud shirt aan en leg een knoeimat neer."],"say":["Kijk, de rode druppel blijft bovenop het schuim liggen!","Wat gebeurt er als je met je stokje door blauw en geel gaat?","Ik zie een krul hier en een slinger daar. Welke vind jij het spannendst?","Tel je mee? Eén, twee, drie, vier, vijf… en nu héél voorzichtig optillen."],"words":["schuim","druppel","krul","slinger","afdruk","luchtig"],"learn":["creativiteit","zintuigen","ontdekken"],"tips":["Werk naast de gootsteen of in een lege badkuip: dan spoel je alles direct weg.","Zet het dienblad op een oude handdoek die het schuim opvangt dat over de rand gaat."],"variations":["Herfst: maak bruin-rood-gele vellen en knip er bladeren uit.","Kerst: knip van groen-wit marmerpapier kerstboompjes voor een kaart.","Inpakpapier: marmer een groot vel en pak er een cadeautje mee in."],"themes":[]},
  {"id":"speeldeeg-maken","title":"Speeldeeg maken zonder koken","emoji":"🥣","category":"deeg","summary":"Weeg, roer en kneed samen je eigen zachte speeldeeg in jullie lievelingskleur: zelf maken is de helft van de pret.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":30,"supervision":1,"materials":[{"id":"bloem","note":"250 g"},{"id":"zout","note":"125 g fijn zout"},{"id":"olie","note":"2 el"},{"id":"water","note":"ca. 200 ml, kokend"},{"id":"kookplaat","note":"of waterkoker, voor het kokende water"},{"id":"kom","note":"een grote"},{"id":"lepel","note":"een stevige (houten) lepel om te roeren"},{"id":"kleurstof","note":"een paar druppels per kleur"}],"optional":[{"id":"zip-zakjes","note":"om de kleur zonder vlekken door te kneden, en om te bewaren"},{"id":"potjes","note":"afgesloten bakjes om het deeg in te bewaren"},{"id":"oud-shirt"}],"steps":["Weeg samen 250 g bloem en 125 g zout af in een grote kom. Je kind mag strooien en roeren.","Doe er 2 el olie bij, en eventueel 1 el citroensap: dan blijft het deeg langer goed.","Giet er ca. 200 ml kokend water bij en roer met een lepel tot alles samenkomt (dat doe jij; je kind kijkt op afstand).","Laat het deeg een paar minuten afkoelen. Voel eerst zelf of het niet meer heet is.","Kneed het deeg samen glad op tafel. Plakt het? Strooi er dan een beetje bloem bij.","Verdeel het in bollen, maak er een kuiltje in en druppel er kleurstof in. Kneed de kleur erdoor, het liefst in een ritszakje.","Bewaar het deeg in een afgesloten bakje of zakje in de koelkast: zo blijft het 1-2 weken goed."],"ageTips":{"young":"Een tweejarige kan vooral strooien, roeren in de droge bloem en kneden zodra het deeg lauw is. Geef je peuter een eigen klein bolletje om alvast mee te knijpen.","old":"Laat je kleuter zelf afwegen (wanneer staat de weegschaal op 250?), de lepels olie tellen en een mengkleur bedenken: wat krijg je als je geel en blauw deeg door elkaar kneedt?"},"safety":["Kokend water: dat doe jij. Zet de kom ver van de tafelrand en laat je kind pas meekneden als het deeg lauw is.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Rauwe bloem kan bacteriën bevatten: proeven is niet de bedoeling. Proeft je kind veel, verhit de bloem dan eerst 5 minuten op 175 °C in de oven en laat hem afkoelen."],"say":["Kneden, kneden, kneden!","Hoe voelt het deeg nu: warm, zacht of plakkerig?","Wat denk je dat er gebeurt als we blauw en geel door elkaar kneden?","Ik zie dat het deeg rood wordt, en je handen ook een beetje!","Wat heb jij stevig gekneed, je armen zijn vast moe!"],"words":["afwegen","roeren","kneden","plakkerig","zacht","warm","mengen","bolletje"],"learn":["fijne-motoriek","rekenen","zintuigen","ontdekken"],"tips":["Kneed de kleurstof door het deeg in een ritszakje: geen vlekken op handen en tafel.","Te plakkerig? Een beetje bloem erbij. Te droog of brokkelig? Kneed er een paar druppels olie of water door.","Haal het deeg een kwartiertje voor het spelen uit de koelkast, dan is het weer lekker soepel."],"variations":["Sinterklaas: kneed er 1 tl speculaaskruiden door voor geurig, bruin deeg.","Kerst: maak rood en groen deeg en steek er sterren en boompjes uit.","Regenboog: verdeel het deeg in zes bolletjes en geef elk een eigen kleur."],"themes":[]},
  {"id":"zoutdeeg","title":"Zoutdeeg-hangers en afdrukjes","emoji":"🧂","category":"deeg","summary":"Kneed zoutdeeg, steek hangers uit of maak een handafdruk, droog ze in de oven en beschilder ze: een cadeautje dat jaren meegaat.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":30,"supervision":1,"materials":[{"id":"bloem","note":"200 g"},{"id":"zout","note":"100 g fijn zout"},{"id":"water","note":"±125 ml lauw water"},{"id":"kom"},{"id":"deegroller"},{"id":"uitsteekvormpjes","note":"of een glas om rondjes uit te steken"},{"id":"rietjes","note":"om een ophanggaatje te prikken"},{"id":"bakpapier"},{"id":"oven"},{"id":"plakkaatverf","note":"om te beschilderen als alles droog is"},{"id":"penselen"}],"optional":[{"id":"touw","note":"lint of touw om de hanger op te hangen"},{"id":"mes","note":"om een rondje om de handafdruk te snijden (dat doe jij)"},{"id":"knutsellijm","note":"verdund met wat water als glanslaagje"},{"id":"oud-shirt"}],"steps":["Meng samen 200 g bloem en 100 g zout in een kom. Giet er beetje bij beetje ±125 ml lauw water bij en kneed tot een stevig, glad deeg.","Rol het deeg op bakpapier uit tot ongeveer een halve centimeter dik. Voor een handafdruk maak je een plak van ruim 1 cm.","Steek vormpjes uit. Voor een handafdruk druk je de hand van je kind stevig in het deeg en snijd je er een rondje omheen (dat doe jij).","Prik met een rietje een gaatje bovenin, zodat je de hanger later kunt ophangen.","Droog alles op de bakplaat 1-3 uur in de oven op 100-120 °C (dat doe jij), of 2-3 dagen aan de lucht. Dikke stukken hebben langer nodig.","Laat alles helemaal afkoelen en beschilder het dan met plakkaatverf. Rijg er een lintje door als de verf droog is."],"ageTips":{"young":"Een tweejarige vindt kneden, prikken en vormpjes drukken het leukst. Rol jij het deeg uit; je peuter drukt de vormpjes met twee handen. Bij een handafdruk druk jij zachtjes mee terwijl jullie tot drie tellen.","old":"Laat je kleuter zelf het water afmeten en kneden, met een potlood een naam of jaartal in de achterkant krassen en bedenken welke hanger voor wie is."},"safety":["Zoutdeeg bevat veel zout: niet opeten, en giftig voor honden. Hang de hangers hoog in de kerstboom als je een hond hebt.","De oven en de bakplaat zijn heet: dat doe jij. Laat alles op de plaat afkoelen voordat je kind het pakt.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Druk! Hard drukken!","Hoe voelt het deeg: korrelig of glad?","Ik zie al je vingers in het deeg staan, zelfs je duim!","Wie krijgt deze hanger, denk je?","Wat schilder je zorgvuldig, je neemt echt de tijd."],"words":["kneden","uitrollen","uitsteken","afdruk","gaatje","korrelig","hard","drogen"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Bobbelt het deeg in de oven? Zet de oven lager (100 °C) en droog wat langer.","Een laagje verdunde knutsellijm na het verven maakt de hanger glanzend en steviger.","Overgebleven deeg blijft in een afgesloten zakje in de koelkast nog een paar dagen goed."],"variations":["Kerst: steek sterren, boompjes en hartjes uit voor in de kerstboom.","Moederdag: maak een hartje met de vingerafdrukken van je kind en rijg er een lint door.","Herfst: rol een blad over het deeg en bekijk de nerven in de afdruk.","Naambordje: steek een groot rondje uit en kras er samen de naam van je kind in, voor op de kamerdeur."],"themes":["kerst","cadeau","moederdag"]},
  {"id":"wolkendeeg","title":"Wolkendeeg: zacht maanzand","emoji":"☁️","category":"deeg","summary":"Met alleen bloem en olie maak je wolkendeeg: zo zacht als een wolk, kruimelig als zand en toch te vormen tot taartjes en bergen.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":30,"supervision":2,"materials":[{"id":"bloem","note":"500 g"},{"id":"olie","note":"125 ml zonnebloemolie (of babyolie, dan niet om te proeven)"},{"id":"opbergbak","note":"een grote bak om in te mengen en te spelen"}],"optional":[{"id":"uitsteekvormpjes","note":"of zandvormpjes"},{"id":"plastic-bekers","note":"om taartjes mee te maken"},{"id":"lepel","note":"om te scheppen"},{"id":"klein-speelgoed","note":"diertjes of autootjes om te verstoppen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Leg een knoeimat neer en zet een grote bak op de vloer of tafel: wolkendeeg komt overal.","Doe 500 g bloem in de bak en giet er 125 ml olie over.","Wrijf en kneed het samen met je handen door elkaar tot het kruimelig is, maar een bal blijft als je erin knijpt. Te droog? Nog een scheutje olie.","Geef bekertjes, vormpjes en lepels: bak zandtaartjes, bouw bergen en graaf tunnels.","Verstop diertjes of autootjes in het deeg en laat je kind ze weer opgraven.","Bewaar het wolkendeeg in een afgesloten bak: het blijft een paar weken goed. Veeg of zuig kruimels eerst droog op; een natte doek maakt er pap van."],"ageTips":{"young":"Een tweejarige schept en graaft het liefst. Geef één grote lepel, een beker en een paar grote diertjes, en speel in een bak met een hoge rand.","old":"Laat je kleuter zelf afmeten en mengen, een maanlandschap bouwen met kraters en een raket van een wc-rolletje, of zandtaartjes tellen en verkopen."},"safety":["Rauwe bloem kan bacteriën bevatten: niet opeten. Proeft je kind veel, verhit de bloem dan eerst 5 minuten op 175 °C in de oven, laat hem afkoelen en gebruik zonnebloemolie in plaats van babyolie.","Kruimels met olie maken de vloer glad: veeg ze direct op.","Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: verstop voor je peuter alleen grote speeltjes."],"say":["Knijp… en het blijft een bal!","Hoe voelt het: zacht, koel of een beetje vettig?","Wat gebeurt er als je de bal weer loslaat en erop drukt?","Ik zie dat je een hele hoge berg bouwt.","Graven! Wie zit daar verstopt?"],"words":["kruimelig","zacht","knijpen","graven","scheppen","vormpje","berg","verstoppen"],"learn":["zintuigen","fijne-motoriek","creativiteit","ontdekken"],"tips":["Speel op een oud laken of in de lege badkuip: schud het laken daarna uit boven de vuilnisbak of veeg de badkuip leeg met een stoffer.","Olie kan vetvlekjes geven op kleding en vloerkleed: trek oude kleren aan en speel liever op een gladde vloer.","Wolkendeeg is goedkoop: huismerkbloem en gewone zonnebloemolie werken prima."],"variations":["Zomer: zet er schelpen en emmertjes bij en bouw een zandkasteel.","Bouwplaats: laat graafmachines en vrachtautootjes het deeg verplaatsen.","Geurdeeg: meng er 1 el kaneel of speculaaskruiden door voor een bruine, geurige versie.","Maanlandschap: druk kraters met een bal en laat een raket van een wc-rolletje landen."],"themes":[]},
  {"id":"sneeuwdeeg","title":"Sneeuwdeeg van maizena","emoji":"⛄","category":"deeg","summary":"Kneed maizena en conditioner tot koel, zijdezacht sneeuwdeeg en bouw binnen sneeuwpoppen, iglo’s en een winterlandschap voor je speelgoeddieren.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":25,"supervision":2,"materials":[{"id":"maizena","note":"200 g"},{"id":"conditioner","note":"100 ml; liefst mild en zonder sterke geur"},{"id":"kom","note":"of een bak om in te mengen"}],"optional":[{"id":"dienblad","note":"met randje, om op te spelen"},{"id":"klein-speelgoed","note":"pinguïns, ijsberen of andere diertjes"},{"id":"takjes","note":"als bomen of als armen voor de sneeuwpop"},{"id":"koelkast","note":"voor extra koude sneeuw"}],"steps":["Doe 200 g maizena in een kom en laat je kind er eerst in voelen: hoor je het knerpen als je knijpt?","Giet er 100 ml conditioner bij en kneed met je handen tot een zacht deeg dat aan elkaar plakt als je knijpt. Te plakkerig? Nog wat maizena erbij.","Leg het deeg 15 minuten in de koelkast als je het extra koud wilt: dan voelt het nog meer als sneeuw.","Rol balletjes en bouw samen sneeuwpoppen: een grote bal onderop, een kleine erbovenop, takjes als armen.","Zet speelgoeddieren in de sneeuw: laat ze sporen maken, een iglo bouwen of verstoppertje spelen.","Bewaar het deeg een paar dagen in een afgesloten bakje. Gooi restjes in de vuilnisbak, niet door de gootsteen."],"ageTips":{"young":"Een tweejarige vindt knijpen en verkruimelen het leukst. Speel op een dienblad met rand, geef een lepel en een bekertje en houd een doekje klaar voor de handjes.","old":"Laat je kleuter zelf afwegen (200 g maizena, 100 ml conditioner) en een heel winterdorp bouwen. Hoeveel sneeuwballen heb je nodig voor drie sneeuwpoppen?"},"safety":["Conditioner is niet om te eten en prikt in de ogen: houd een doekje klaar en was handen na afloop. Stopt je kind nog alles in de mond, kies dan eetbaar havermoutdeeg.","Gemorste maizena maakt de vloer spiegelglad: veeg het meteen op."],"say":["Brrr, koud! Voel je dat?","Hoor je het knerpen als je knijpt?","Wat gebeurt er als je een bal rolt en hem dan platdrukt?","Ik zie pootafdrukken in de sneeuw. Van wie zouden die zijn?","Wat heb je lang en geduldig gerold!"],"words":["sneeuw","koud","zijdezacht","knerpen","rollen","sneeuwpop","spoor","bovenop"],"learn":["zintuigen","fijne-motoriek","creativiteit","taal"],"tips":["Speel op een dienblad of bakplaat met rand: de kruimels blijven dan bij elkaar.","Neem de goedkoopste conditioner; zonder sterke geur is het fijner voor de huid en de neus."],"variations":["Poolgebied: zet pinguïns en ijsberen in de sneeuw en bouw een iglo van bolletjes.","Kerst: prik groene takjes als kerstboompjes in de sneeuw en geef de sneeuwpop een sjaaltje van vilt.","Sporen raden: laat autootjes of dierenpootjes sporen maken en raad samen van wie ze zijn."],"themes":["winter","kerst"]},
  {"id":"eetbaar-deeg","title":"Eetbaar speeldeeg voor de kleinsten","emoji":"🌾","category":"deeg","summary":"Maak zacht deeg van havermout, olie en water dat je dreumes gerust mag proeven: knijpen, prikken en platslaan zonder zorgen.","ageMin":1,"ageMax":2,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"havermout","note":"100 g"},{"id":"blender","note":"of staafmixer, om de havermout fijn te malen"},{"id":"olie","note":"1 el zonnebloemolie"},{"id":"water","note":"±5-6 el"},{"id":"kom"}],"optional":[{"id":"dienblad","note":"of het blad van de kinderstoel"},{"id":"uitsteekvormpjes","note":"grote, zonder scherpe randjes"},{"id":"plastic-bekers","note":"om rondjes mee uit te steken"}],"steps":["Maal 100 g havermout in de blender tot fijn meel (dat doe jij).","Doe het meel in een kom met 1 el olie en voeg lepel voor lepel water toe (±5-6 el), tot je een soepel deeg hebt.","Kneed het deeg kort door en geef je dreumes een flinke bol op een dienblad of het blad van de kinderstoel.","Doe voor wat je allemaal kunt: een balletje rollen, een plat koekje slaan, gaatjes prikken met je vinger.","Geef er een bekertje of groot vormpje bij om in te drukken of rondjes mee uit te steken.","Bewaar restjes afgedekt in de koelkast en gebruik ze binnen 1-2 dagen."],"ageTips":{"young":"Een dreumes van 1 ontdekt vooral met handen en mond. Geef één bol zonder spulletjes erbij en benoem wat er gebeurt: plat, rond, een gaatje!","old":"Een tweejarige kan meehelpen met water erbij lepelen en kneden, slangetjes rollen en met een beker koekjes uitsteken. Tel ze samen: één, twee, drie!"},"safety":["Ook eetbaar deeg is plakkerig en kan in de keel blijven steken: laat je dreumes rechtop zitten en blijf erbij als er gehapt wordt.","Havermout bevat vaak sporen van gluten: kies glutenvrije havermout bij coeliakie of een glutenallergie.","Het mes van de blender is vlijmscherp: dat doe jij, en haal de stekker eruit voordat je het meel eruit schept.","Het deeg bederft snel: bewaar het in de koelkast en gooi het na 1-2 dagen weg, of eerder als het zuur ruikt."],"say":["Knijp! Zacht hè?","Plat! Nog eens!","Ik zie dat je er met je vinger een gaatje in prikt.","Hoe ruikt het? Een beetje naar pap?","Wat rol jij goed, met allebei je handen!"],"words":["zacht","plakkerig","knijpen","plat","rond","rollen","prikken","gaatje"],"learn":["zintuigen","fijne-motoriek","taal","ontdekken"],"tips":["Doe het vlak voor het badje: havermout plakt een beetje, maar veegt makkelijk af met een vochtig washandje.","Te plakkerig? Strooi er wat havermoutmeel bij. Te droog? Nog een lepel water."],"variations":["Kleurtje: kneed er een theelepel bietensap of een paar geprakte blauwe bessen door (dat vlekt wel een beetje).","Geurtje: kneed er een snufje kaneel door en ruik er samen aan.","Feestje: steek met een bekertje taartjes uit en zing samen ‘Lang zal ze leven’."],"themes":[]},
  {"id":"deegbakkerij","title":"Bakkertje spelen met speeldeeg","emoji":"🎂","category":"deeg","summary":"Rol, steek uit en versier: je kind is de bakker en bakt koekjes, broodjes en een verjaardagstaart met kaarsjes, en jij komt alles kopen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":25,"supervision":2,"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht, in een paar kleuren"},{"id":"deegroller","note":"of een glazen fles"},{"id":"uitsteekvormpjes","note":"of een beker en een flessendop"},{"id":"rietjes","note":"in stukjes geknipt, als kaarsjes"}],"optional":[{"id":"papieren-bordjes","note":"als taartbordjes"},{"id":"muffinvorm","note":"voor taartjes"},{"id":"ijsstokjes","note":"als taartmes, of als kaarsjes voor peuters"},{"id":"papier","note":"voor prijskaartjes"}],"steps":["Richt samen een bakkerij in: een theedoek als toonbank, bordjes, een deegroller en vormpjes.","Rol het deeg uit en steek koekjes uit, of rol balletjes tot bolletjes en broodjes.","Bak een verjaardagstaart: druk een dikke bol deeg plat op een bord en prik er stukjes rietje in als kaarsjes.","Zing samen ‘Lang zal ze leven’ en blaas de kaarsjes uit. Trek ze er dan één voor één weer uit.","Speel winkeltje: jij komt kopen. Mag ik drie koekjes? Tel ze samen uit: één, twee, drie!","Ruim op door het deeg per kleur terug te stoppen in een afgesloten bakje."],"ageTips":{"young":"Een tweejarige rolt, prikt en drukt het liefst. Geef zacht, soepel deeg en grote vormpjes, en gebruik hele rietjes of ijsstokjes als kaarsjes.","old":"Laat je kleuter prijskaartjes tekenen, bestellingen opnemen (twee rode koekjes en één taart) en het wisselgeld tellen. Hoeveel kaarsjes horen er op een taart voor een vijfjarige?"},"safety":["Speeldeeg bevat veel zout: niet opeten, en giftig voor honden; houd het buiten bereik van huisdieren. Proeft je peuter veel, kies dan eetbaar havermoutdeeg.","Stukjes rietje passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Gebruik voor je peuter hele rietjes of ijsstokjes."],"say":["Rollen, rollen… plat!","Mag ik drie koekjes, alstublieft?","Hoe oud is de jarige? Hoeveel kaarsjes moeten erop?","Ik zie dat je de koekjes netjes naast elkaar legt.","Wat bak jij een bijzondere taart, hoe heb je dat bedacht?"],"words":["bakker","rollen","uitsteken","taart","kaarsjes","kopen","alstublieft","dank je wel"],"learn":["fijne-motoriek","rekenen","taal","samen"],"tips":["Speel op een dienblad of onderlegger: kruimels deeg blijven dan bij elkaar en plakken niet in het kleed.","Geen vormpjes? Een beker, een flessendop en een vork werken net zo goed."],"variations":["Verjaardag: oefen het feestje met een knuffel als jarige, een taart, kaarsjes en een liedje.","Pizzeria: rol rondjes uit en beleg ze met deegballetjes en -slierten.","Sinterklaas: rol kleine bolletjes als kruidnoten en verkoop ze per zakje.","IJssalon: bolletjes deeg in een bekertje, met een rietje als lepeltje."],"themes":["verjaardag"]},
  {"id":"deegafdrukken","title":"Afdrukken en fossielen in deeg","emoji":"🦕","category":"deeg","summary":"Druk schelpen, blaadjes, vorken en dinopootjes in plat speeldeeg en ontdek welke patronen ze achterlaten: kun jij raden wat het was?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht"},{"id":"vork","note":"voor strepen en ruitjes"},{"id":"klein-speelgoed","note":"bijv. speelgoeddino’s of andere dieren met pootjes"}],"optional":[{"id":"duplo","note":"voor stippenpatronen"},{"id":"schelpen","note":"gladde, hele schelpen"},{"id":"bladeren","note":"met dikke nerven"},{"id":"dennenappels","note":"voor een schubbenpatroon"},{"id":"deegroller","note":"om het deeg plat te rollen"}],"steps":["Rol of druk een paar flinke plakken speeldeeg plat, ongeveer 1 cm dik.","Zoek samen spullen met een mooi patroon: een schelp, een blad met dikke nerven, een vork, een duploblokje, de pootjes van een speelgoeddino.","Druk ze één voor één stevig in het deeg en haal ze er voorzichtig weer uit: kijk, een afdruk!","Speel ‘raad wat het was’: je kind doet de ogen dicht, jij maakt een afdruk en je kind raadt welk voorwerp het was.","Laat de dino’s een spoor door het deeg lopen: wie liep hier, een grote of een kleine?","Kneed het deeg weer tot een bal en begin opnieuw."],"ageTips":{"young":"Een tweejarige drukt het liefst zelf. Geef grote voorwerpen die makkelijk vast te houden zijn, zoals een duploblok of een vork, en druk samen met jouw hand eroverheen.","old":"Laat je kleuter een fossielenmuseum maken: afdrukken op een rij met een naamkaartje erbij. Of leg de voorwerpen ernaast en laat je kleuter ze bij de juiste afdruk zoeken."},"safety":["Kies gladde, hele schelpen: gebroken schelpen hebben scherpe randjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren."],"say":["Druk! En nu… optillen!","Wat zie je in de afdruk: lijntjes, rondjes of stippen?","Welk voorwerp heeft dit gemaakt, denk je?","Ik zie dat je heel voorzichtig optilt, zo blijft de afdruk mooi.","Hoe voelt de schelp: glad of ribbelig?"],"words":["afdruk","drukken","spoor","ribbels","nerven","fossiel","glad","hobbelig"],"learn":["zintuigen","ontdekken","fijne-motoriek","taal"],"tips":["Wil je een afdruk bewaren? Maak hem in zoutdeeg en laat hem drogen in de oven of aan de lucht.","Bewaar een doosje met ‘afdrukspullen’: schelpen en blaadjes van een wandeling, een oude vork en een paar blokjes."],"variations":["Zomer: druk schelpen in het deeg voor een strand vol fossielen en zet er een speelgoedkrab bij.","Herfst: druk blaadjes, dennenappels en takjes in het deeg en bekijk de nerven en schubben.","Dinojacht: verstop speelgoeddino’s, laat sporen achter en zoek de dino bij het spoor.","Rolpatroon: rol een autootje of een vork over het deeg: wat voor spoor geeft dat?"],"themes":["zomer","herfst"]},
  {"id":"deeg-egeltjes","title":"Deeg-egeltjes met spaghettistekels","emoji":"🦔","category":"deeg","summary":"Rol een egel van speeldeeg en prik er stukjes droge spaghetti in als stekels: hoeveel stekels krijgt jouw egel?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"speeldeeg","note":"een bal zo groot als een mandarijn per egel"},{"id":"pasta","note":"droge spaghetti, in stukjes van ±4 cm gebroken"}],"optional":[{"id":"rietjes","note":"in stukjes geknipt: dikker en makkelijker voor peuters"},{"id":"bladeren","note":"voor een herfstbos rond de egels"},{"id":"wiebeloogjes","note":"pas vanaf 3 jaar"}],"steps":["Breek droge spaghetti in stukjes van ongeveer 4 cm (dat doe jij) en leg ze in een bakje.","Rol samen een bal speeldeeg en knijp er aan één kant een puntje aan: de snuit van de egel.","Prik de stekels één voor één in de rug van de egel. Hoeveel passen erop?","Rol twee kleine deegbolletjes als oogjes en een iets grotere als neus, of druk de ogen in met een potlood.","Leg bladeren neer als herfstbos en zet de egels erin.","Trek de stekels er na het spelen uit, gooi gebroken stukjes weg en bewaar het deeg in een afgesloten bakje."],"ageTips":{"young":"Een tweejarige prikt makkelijker met dikkere stekels, zoals stukjes rietje. Geef ze één voor één aan en help de egel stevig vast te houden.","old":"Laat je kleuter een egelfamilie maken: een grote, een middelste en een kleine. Wie heeft de meeste stekels? Tel en vergelijk, of maak een patroon met lange en korte stekels."},"safety":["Droge spaghetti breekt in kleine, scherpe stukjes: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij je peuter en ruim gebroken stukjes meteen op.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Gebruik geen wiebeloogjes of kralen als oogjes bij kinderen onder de 3: maak de oogjes van deeg."],"say":["Prik! Nog een stekel!","Au, puntig! Hoe voelen de stekels?","Hoeveel stekels heeft jouw egel al?","Ik zie dat je de stekels heel voorzichtig rechtop zet.","Wat zou een egel eten, denk je?"],"words":["egel","stekels","prikken","puntig","rond","snuit","winterslaap"],"learn":["fijne-motoriek","rekenen","concentratie","creativiteit"],"tips":["Breek de spaghetti in een theedoek: dan vliegen er geen stukjes door de keuken.","Bewaar het deeg en de stekels samen in een afgesloten bakje: een kant-en-klaar herfstspelletje."],"variations":["Herfst: bouw een bladerhoopje als winterslaapnest en stop de egels erin.","Verjaardag: maak een taart van deeg en prik er spaghetti in als kaarsjes.","Monsters: prik er pijpenragers met omgevouwen puntjes en rietjes in als haar en voelsprieten.","Cactus: groen deeg met spaghettistekels in een bekertje als bloempot."],"themes":["herfst"]},
  {"id":"papier-mache","title":"Papier-maché-kommetje","emoji":"📰","category":"deeg","summary":"Plak laagjes krant met zelfgemaakt plaksel over een kom en beschilder het kommetje als het hard is: heerlijk kliederen met iets om te bewaren.","ageMin":4,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":30,"supervision":2,"materials":[{"id":"kranten","note":"in repen en snippers gescheurd"},{"id":"bloem","note":"100 g, voor het plaksel"},{"id":"water","note":"200 ml, voor het plaksel"},{"id":"zout","note":"een snufje"},{"id":"kom","note":"één als mal en één voor het plaksel"},{"id":"huishoudfolie","note":"of aluminiumfolie, om de mal in te pakken"},{"id":"plakkaatverf","note":"om te beschilderen als het droog is"},{"id":"penselen"}],"optional":[{"id":"keukenpapier","note":"als witte laag, dan zie je welke laag nieuw is"},{"id":"knutsellijm","note":"verdund met wat water als glanslaagje"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Scheur samen kranten in repen en snippers van ongeveer 2 bij 5 cm. Scheuren is al een prima klus voor je kleuter.","Maak het plaksel: roer 100 g bloem met 200 ml water glad in een kom en doe er een snufje zout door.","Zet een andere kom ondersteboven op tafel en pak hem strak in met huishoudfolie.","Haal een snipper door het plaksel, strijk het overtollige plaksel eraf tussen twee vingers en plak hem op de kom. Leg de snippers dakpansgewijs over elkaar.","Plak zo 3-4 lagen over de hele kom. Wissel krant af met keukenpapier, dan zie je waar de nieuwe laag zit.","Laat het kommetje 1-2 dagen drogen op een warme plek. Haal het dan voorzichtig van de mal, trek de folie eruit en knip de rand recht (dat doe jij).","Beschilder het kommetje met plakkaatverf en laat het weer drogen."],"ageTips":{"young":"Voor een vierjarige zijn kleine snippers lastig: gebruik grotere repen en maak twee of drie lagen. Of beplak een papieren bordje als plat schaaltje, dat is sneller af.","old":"Een vijfjarige kan zelf de lagen tellen (krant, wit, krant…), een ontwerp bedenken voor het schilderen, zoals stippen, strepen of een dierengezicht, en vertellen wat er in het kommetje komt."},"safety":["Plaksel is gemaakt van rauwe bloem: niet proeven, en was handen na afloop.","Het kommetje is niet geschikt voor eten of drinken: gebruik het voor sieraden, sleutels of andere spulletjes.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Plak, strijk, nog een!","Hoe voelt het plaksel? Glibberig en koud!","Ik zie dat je de snippers netjes over elkaar legt, als dakpannen.","Hoeveel lagen hebben we nu: één, twee of drie?","Wat werk je geduldig, laagje na laagje! Wat wil jij in je kommetje bewaren?"],"words":["plaksel","glibberig","snipper","laag","scheuren","gladstrijken","drogen","hard"],"learn":["fijne-motoriek","creativiteit","concentratie","ontdekken"],"tips":["Werk op een oud laken of een opengeknipte vuilniszak: plaksel droogt op tot harde korstjes.","Gooi restjes plaksel in de vuilnisbak, niet door de gootsteen: het wordt hard in de afvoer.","Haast? Laat het kommetje drogen op de verwarming of in de zon voor het raam."],"variations":["Cadeau: een sieradenbakje voor mama of oma, met een glanslaagje van verdunde knutsellijm.","Vaderdag: een bakje voor sleutels of muntjes, beschilderd in papa’s lievelingskleur.","Zonder verf: plak als laatste laag vloeipapier of servetjes, dan is het kommetje meteen gekleurd."],"themes":["cadeau"]},
  {"id":"kleurenjacht","title":"Kleurenjacht door het huis","emoji":"🔴","category":"zintuigen","summary":"Kies een kleur en ga samen op jacht: alles wat rood is, mag mee naar het rode vel papier.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"gekleurd-papier","note":"een vel per kleur, bijv. rood, geel en blauw"}],"optional":[{"id":"wasmand","note":"om de buit in te verzamelen"}],"steps":["Leg een paar vellen gekleurd papier op de vloer, bijvoorbeeld rood, geel en blauw.","Kies samen één kleur en wijs iets in de kamer aan dat die kleur heeft.","Ga op jacht: je kind zoekt spullen in die kleur en legt ze op het juiste vel.","Bekijk samen de buit: wat is het, is het groot of klein, zacht of hard?","Ruim op door alles terug te brengen: waar woont de rode beker?"],"ageTips":{"young":"Begin met één kleur en leg zelf alvast drie rode dingen klaar om te vinden. Benoem alleen kleur en voorwerp: rood, een rode bal!","old":"Zoek binnen één minuut vijf dingen, of sorteer van licht- naar donkerblauw. Ook leuk: zoek iets dat rond én geel is."},"safety":["Let op kleine voorwerpen die je kind onderweg vindt, zoals munten, kraaltjes of knoopcelbatterijen: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Ik zie iets roods… zie jij het ook?","Is deze sok rood of oranje? Wat denk jij?","Je hebt al vier rode dingen gevonden. Zullen we ze tellen?","Rood! Nog een!"],"words":["rood","geel","blauw","licht","donker","hetzelfde","anders"],"learn":["taal","rekenen","grove-motoriek"],"tips":["Speel het als opruimspel: laat je kind alle blauwe spullen terugbrengen naar hun plek.","Maak een foto van elke kleurenstapel: zo heb je meteen een eigen kleurenboekje."],"variations":["Vormenjacht: zoek alles wat rond is, of alles wat vierkant is.","Herfst: zoek bruin, oranje en geel en leg er kastanjes en bladeren bij.","Koningsdag: zoek alles wat oranje is en maak er een oranje tentoonstelling van."],"themes":[]},
  {"id":"bruisvulkaan","title":"Bruisende vulkaan","emoji":"🌋","category":"proefjes","summary":"Giet azijn bij baking soda en kijk hoe er gekleurde schuimlava uit je vulkaan borrelt: elke keer een spannende uitbarsting.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"baking-soda","note":"±2 el, genoeg voor een paar uitbarstingen"},{"id":"azijn","note":"natuurazijn, ±50 ml per uitbarsting"},{"id":"afwasmiddel","note":"een scheutje, voor dik schuim"},{"id":"kleurstof","note":"rood of oranje, voor echte ‘lava’"},{"id":"plastic-bekers","note":"een smalle beker of klein leeg flesje als krater, plus een beker voor de azijn"},{"id":"opbergbak","note":"een afwasteil of bak met hoge rand die de lava opvangt"}],"optional":[{"id":"pipet","note":"om de azijn druppel voor druppel toe te voegen"},{"id":"speeldeeg","note":"om een berg rond de beker te boetseren"},{"id":"oud-shirt"}],"steps":["Zet de bak op tafel of op de vloer en zet een plastic beker in het midden: dat is de krater.","Schep samen 2 el baking soda in de beker en doe er een scheutje afwasmiddel en een paar druppels kleurstof bij.","Schenk ±50 ml azijn in een tweede beker en geef die aan je kind.","Tel samen af: drie, twee, één… en giet de azijn in één keer in de krater!","Kijk: het schuim bruist omhoog en stroomt over de rand. Nog een keer? Giet er nieuwe azijn bij, of leeg de beker en begin opnieuw.","Spoel na afloop alles door de gootsteen en neem de bak af met een doekje."],"ageTips":{"young":"Geef je peuter een klein bekertje met een bodempje azijn: zelf gieten is het allerleukste. Doe de baking soda en kleurstof er zelf in en houd het bij één woord: bruisen!","old":"Laat je kleuter voorspellen en testen: wat gebeurt er zonder afwasmiddel? En met een klein scheutje of met een hele beker azijn? Of boetseer samen een berg van speeldeeg om de beker en bedenk er een verhaal bij."},"safety":["Azijn prikt in de ogen en in wondjes: spoel bij een spatje meteen met lauw water en laat je kind niet in de ogen wrijven.","Baking soda, azijn en afwasmiddel zijn niet om te eten of te drinken: houd de flessen zelf vast en zet ze na het afmeten buiten bereik.","Kleurstof vlekt op kleding, tafel en voegen, en gemorst schuim maakt de vloer glad: werk in de bak, trek een oud shirt aan en veeg morsen meteen op."],"say":["Wat denk je dat er gebeurt als we de azijn erbij gieten?","Hoor je dat? Het sist en knispert!","Ik zie bubbels over de rand kruipen, net echte lava.","Je goot heel voorzichtig: bijna alles kwam in de krater.","Bruisen! Nog een keer?"],"words":["bruisen","schuim","bubbels","vulkaan","uitbarsting","sissen","overstromen"],"learn":["ontdekken","zintuigen","taal"],"tips":["Een liter natuurazijn en een pak baking soda zijn goedkoop en genoeg voor een hele middag uitbarstingen.","Doe het in de lege badkuip of vlak voor badtijd: de lava spoel je daar zo weg, en je kind kan meteen in bad."],"variations":["Regenboogvulkaan: zet vijf bekertjes met elk een andere kleur naast elkaar in de bak en laat ze om de beurt uitbarsten.","Dinovulkaan: zet plastic dinootjes rond de krater en laat ze op tijd wegvluchten voor de lava.","Halloween: kleur het schuim groen en laat een ‘heksenketel’ overkoken in een grote kom."],"themes":[]},
  {"id":"bruisende-kleuren","title":"Bruisende kleuren met een pipet","emoji":"🧪","category":"proefjes","summary":"Druppel gekleurde azijn op een laagje baking soda en zie het overal bruisen en knisperen in rood, geel en blauw.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"baking-soda","note":"±150 g voor een dun laagje op het dienblad"},{"id":"azijn","note":"±200 ml, verdeeld over 3 potjes"},{"id":"kleurstof","note":"rood, geel en blauw"},{"id":"potjes","note":"3 kleine bakjes of glaasjes"},{"id":"pipet","note":"liefst één per kleur"},{"id":"dienblad","note":"met randje; een ovenschaal kan ook"}],"optional":[{"id":"muffinvorm","note":"om de potjes stevig in te zetten"},{"id":"oud-laken","note":"als knoeimat onder het dienblad"},{"id":"klein-speelgoed","note":"grote plastic diertjes om te begraven en vrij te bruisen"},{"id":"oud-shirt"}],"steps":["Strooi een dun laagje baking soda over het dienblad en strijk het een beetje glad met de bolle kant van een lepel.","Verdeel de azijn over drie potjes en doe in elk potje een paar druppels kleurstof: rood, geel en blauw.","Doe voor hoe de pipet werkt: knijp het bolletje in, steek de punt in de azijn, laat los en knijp hem boven het blad weer leeg.","Laat je kind druppels op de baking soda maken: overal waar een druppel valt, bruist het in kleur.","Druppel samen geel bij blauw of rood bij geel. Welke nieuwe kleur ontstaat er?","Strooi er een nieuw laagje baking soda over als het nergens meer bruist. Klaar? Spoel het dienblad af boven de gootsteen."],"ageTips":{"young":"Een pipet is voor een tweejarige nog lastig. Geef een theelepel om de azijn mee te scheppen en te gieten, en zet maar één kleur tegelijk neer.","old":"Laat je kleuter eerst voorspellen welke kleur er ontstaat als je twee kleuren mengt, en pas daarna druppelen. Of teken met druppels een letter, een lachend gezichtje of een regenboog."},"safety":["Azijn prikt in de ogen: knijp de pipet nooit richting gezichten en spoel bij een spatje meteen met lauw water.","Kleurstof vlekt op kleding, hout en voegen: leg een knoeimat neer en trek een oud shirt aan.","Baking soda en azijn zijn niet om te eten of te drinken: zet de fles azijn na het inschenken buiten bereik."],"say":["Knijpen, loslaten… zie je de azijn in de pipet kruipen?","Hoor je het knisperen als de druppel valt?","Wat denk je dat er gebeurt als geel en blauw elkaar raken?","Ik zie een groene vlek! Hoe komt die daar?","Druppel! Bruis!"],"words":["druppel","knijpen","loslaten","bruisen","mengen","oranje","groen","paars"],"learn":["fijne-motoriek","ontdekken","concentratie"],"tips":["Geen pipet? Een medicijnspuitje, een theelepel of een rietje met je vinger op het gaatje werkt ook.","Zet de potjes in een muffinvorm: dan staan ze stevig en vallen ze minder snel om."],"variations":["Verstopte schatten: begraaf een paar grote plastic diertjes in een dikker laagje baking soda en bruis ze met de pipet weer vrij.","Bruisende ijsblokjes: meng baking soda met een beetje gekleurd water tot een dikke pap, vries die in een ijsblokjesvorm in en druppel er azijn op.","Winter: strooi een sneeuwpop van baking soda op een donker bord en laat hem met druppels azijn bruisend smelten."],"themes":[]},
  {"id":"drijven-zinken","title":"Drijft het of zinkt het?","emoji":"⛵","category":"proefjes","summary":"Raad eerst en test dan: welke spullen uit huis blijven drijven in een bak water en welke zakken plons naar de bodem?","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"opbergbak","note":"of een afwasteil, half vol water"},{"id":"water","note":"lauw"},{"id":"kurken","note":"drijven altijd"},{"id":"lepel","note":"een metalen lepel, die zinkt"},{"id":"fruit","note":"bijv. een appel en een sinaasappel"},{"id":"duplo","note":"een paar grote bouwblokken"},{"id":"aluminiumfolie","note":"een vel van ±30 cm voor een bootje"},{"id":"handdoek","note":"onder de bak en om af te drogen"}],"optional":[{"id":"steentjes","note":"een flinke kiezel die niet door een wc-rolletje past"},{"id":"badspeelgoed"},{"id":"papier","note":"voor een lijstje: drijft of zinkt"}],"steps":["Zet de bak op een handdoek op de vloer of tafel en vul hem half met lauw water.","Verzamel samen een stuk of acht voorwerpen, zoals een kurk, een metalen lepel, een appel, een bouwblok en een grote kiezel.","Pak één voorwerp en vraag eerst: wat denk je, blijft het drijven of zakt het naar de bodem?","Laat je kind het voorwerp in het water leggen en kijk samen of de gok klopte. Leg het daarna op de drijf- of de zinkstapel.","Vouw van aluminiumfolie een bootje en laat het drijven. Hoeveel blokjes kan het dragen voordat het zinkt?","Droog alles af op de handdoek en giet het water weg, of geef de planten er water mee."],"ageTips":{"young":"Voor een tweejarige is plonzen en weer opvissen al een feest. Kies grote, onbreekbare voorwerpen en zeg na elke plons alleen: drijft! of zinkt! Het raden komt later vanzelf.","old":"Laat je kleuter vooraf een lijstje maken met twee rijtjes, drijven en zinken, en een vinkje zetten bij elke goede gok. Ook spannend: drijft een sinaasappel met schil, en zonder schil?"},"safety":["Laat je kind nooit alleen bij de bak water, ook niet bij een laagje: blijf er de hele tijd bij.","Kies voor kinderen onder de 3 alleen grote voorwerpen: alles wat door een wc-rolletje past, is te klein (verstikkingsgevaar).","Dweil gemorst water meteen op: een natte vloer is glad."],"say":["Wat denk je: drijft de appel of zinkt hij?","Plons! Helemaal naar de bodem.","Ik zie dat de kurk steeds weer bovenkomt, ook als je hem onderduwt.","Wat goed dat je eerst nadacht voordat je ging testen.","Drijft! Nog een?"],"words":["drijven","zinken","zwaar","licht","bodem","bovenop","plons","nat"],"learn":["ontdekken","taal","rekenen"],"tips":["Laat je kind zelf voorwerpen zoeken die nat mogen worden: dat is de helft van het plezier.","Doe het proefje in de lege badkuip met een laagje water, vlak voor badtijd: dan mag het lekker spetteren."],"variations":["Fruitschaal-test: probeer een banaan, een citroen, een mandarijn en een stuk komkommer. Wat had je niet verwacht?","Bootjesrace: blaas met een rietje je folieboot naar de overkant van de bak.","Toveren met klei: een bolletje klei zinkt, maar maak je er een bakje van, dan blijft het drijven. Hoe kan dat?"],"themes":[]},
  {"id":"dansende-melk","title":"Dansende kleuren in melk","emoji":"🥛","category":"proefjes","summary":"Druppel kleurstof in een laagje melk, raak het aan met een wattenstaafje met afwasmiddel en kijk hoe de kleuren wegschieten en dansen.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"melk","note":"volle melk, een laagje van ±1 cm"},{"id":"bord","note":"een diep bord of schaaltje"},{"id":"kleurstof","note":"3-4 kleuren"},{"id":"afwasmiddel","note":"een bodempje op een schoteltje"},{"id":"wattenstaafjes","note":"een paar"}],"optional":[{"id":"dienblad","note":"onder het bord, voor gemorste melk"},{"id":"pipet","note":"om de kleurstof te druppelen"},{"id":"koffiefilters","note":"om een afdruk van de kleuren te maken"}],"steps":["Giet een laagje volle melk van ongeveer een centimeter in een diep bord en laat het even stil worden.","Druppel drie of vier druppels kleurstof in verschillende kleuren dicht bij elkaar in het midden. Niet roeren!","Doe een bodempje afwasmiddel op een schoteltje en laat je kind het puntje van een wattenstaafje erin dopen.","Houd het wattenstaafje rustig midden in de melk, tussen de kleuren, en tel tot tien. Kijk hoe de kleuren wegschieten en draaien!","Probeer een andere plek of dop het wattenstaafje opnieuw. Stopt het dansen? Druppel er nieuwe kleuren bij of begin met verse melk.","Giet de melk na afloop weg en was het bord en de handen goed af."],"ageTips":{"young":"Laat je peuter vooral het wattenstaafje erin houden; het druppelen van de kleurstof doe jij. Twee kleuren is genoeg, en zeg wat je ziet: weg! Ze rennen weg!","old":"Laat je kleuter een patroon bedenken, bijvoorbeeld druppels in een cirkel of op een rij, en voorspellen waar de kleuren heen gaan. Vertel daarna: het afwasmiddel duwt het vet in de melk opzij."},"safety":["Deze melk is niet meer om te drinken: giet hem na afloop meteen weg en houd het schoteltje afwasmiddel bij jezelf. Komt er zeep in een oog, spoel dan met lauw water.","Kleurstof vlekt op kleding en tafel: zet het bord op een dienblad en schuif de mouwen omhoog."],"say":["Kijk eens! De kleuren rennen weg van je stokje.","Wat denk je dat er gebeurt als je het wattenstaafje in het midden houdt?","Ik zie rood en blauw door elkaar draaien. Welke kleur wordt het?","Wat houd je je hand goed stil: daardoor blijven de kleuren dansen.","Dans, kleurtjes, dans!"],"words":["druppel","dansen","draaien","wegschieten","melk","zeep","mengen","stil"],"learn":["ontdekken","zintuigen","concentratie"],"tips":["Volle melk werkt het best: hoe meer vet, hoe wilder de kleuren dansen. Melk die net over de datum is, is prima.","Maak een foto van elk bord: elke keer ontstaat er een ander patroon.","Zet het bord op een dienblad met een theedoek eronder: gemorste melk in een vloerkleed ruik je nog dagen."],"variations":["Vergelijk drie borden: volle melk, halfvolle melk en water. Waar dansen de kleuren het wildst?","Oud en nieuw: tel samen af van tien naar nul en steek dan met het wattenstaafje je kleurenvuurwerk af.","Afdrukje: leg na het dansen voorzichtig een koffiefilter op de melk, til hem op en laat hem drogen: een kleurig kunstwerkje."],"themes":[]},
  {"id":"lopend-water","title":"Regenboog van lopend water","emoji":"🌈","category":"proefjes","summary":"Zet bekers met gekleurd water op een rij, hang er bruggetjes van keukenpapier tussen en zie het water klimmen en nieuwe kleuren mengen.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"plastic-bekers","note":"7 doorzichtige bekers of glazen"},{"id":"water"},{"id":"kleurstof","note":"rood, geel en blauw"},{"id":"keukenpapier","note":"6 vellen"}],"optional":[{"id":"dienblad","note":"om de bekers op te zetten, eventueel in een kring"},{"id":"papier","note":"om je voorspelling op te tekenen"},{"id":"kleurpotloden","note":"in dezelfde kleuren als het water"}],"steps":["Zet zeven bekers op een rij. Vul de eerste, derde, vijfde en zevende beker voor driekwart met water; de bekers ertussen blijven leeg.","Laat je kind kleurstof druppelen: rood in de eerste, geel in de derde, blauw in de vijfde en weer rood in de zevende beker.","Vouw zes vellen keukenpapier in de lengte een paar keer dubbel tot stevige repen.","Hang de repen als bruggetjes tussen de bekers: één uiteinde in een volle beker, het andere in de lege beker ernaast.","Kijk na tien minuten: het gekleurde water kruipt omhoog door het papier! Kom daarna elk uur even kijken.","Bekijk na een paar uur of de volgende ochtend de lege bekers: welke nieuwe kleuren zijn er ontstaan?","Gooi het natte papier weg, giet het water in de gootsteen en spoel de bekers om."],"ageTips":{"young":"Voor een driejarige is het lang wachten. Begin met drie bekers (geel, leeg, blauw) en kijk samen elke tien minuten: wordt het al groen?","old":"Laat je kleuter vooraf voorspellen welke kleur er in elke lege beker komt en dat tekenen met kleurpotloden. Leg de tekening na afloop naast de bekers: klopte het?"},"safety":["Kleurstof vlekt op kleding, tafel en vloerkleed: zet de bekers op een dienblad op een plek waar ze uren mogen blijven staan.","Zet de opstelling buiten bereik van jongere broertjes, zusjes en huisdieren, en dweil gemorst water meteen op: een natte vloer is glad."],"say":["Kijk, het rode water klimt omhoog in het papier!","Welke kleur denk je dat er komt als rood en geel elkaar ontmoeten?","Ik zie een groen randje in de lege beker. Waar komt dat vandaan?","Wat ben je geduldig: het water werkt nog hard voor ons.","Kijk! Groen!"],"words":["opzuigen","klimmen","mengen","nat","droog","oranje","paars","wachten"],"learn":["ontdekken","rekenen","taal"],"tips":["Wees niet zuinig met kleurstof (zo’n 10 druppels per beker): hoe feller de kleur, hoe mooier de regenboog.","Start het proefje ’s ochtends of vlak voor bedtijd: dan is er na het spelen of bij het ontbijt een regenboog te zien.","Stevig keukenpapier werkt het best: dun servetpapier zakt in elkaar als het nat wordt."],"variations":["Regenboogkring: zet zes bekers in een kring (rood, leeg, geel, leeg, blauw, leeg) en maak een complete kleurencirkel.","Bloemen kleuren: zet een witte bloem of een selderijstengel in water met veel kleurstof en bekijk na een dag de blaadjes.","Lente: laat de gekleurde repen keukenpapier drogen en knip er bloemen of vlinders van voor het raam."],"themes":[]},
  {"id":"pepertruc","title":"Pepertruc: de peper rent weg","emoji":"🧂","category":"proefjes","summary":"Strooi peper op water, doop je vinger in afwasmiddel en kijk hoe alle peperpuntjes in een flits naar de rand vluchten.","ageMin":3,"ageMax":5,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"durationMinutes":10,"supervision":2,"materials":[{"id":"bord","note":"een diep bord, liefst wit"},{"id":"water"},{"id":"kruiden","note":"gemalen zwarte peper"},{"id":"afwasmiddel","note":"een druppel op een schoteltje"}],"optional":[{"id":"wattenstaafjes","note":"om het afwasmiddel op te doen in plaats van een vinger"}],"steps":["Vul een diep bord met een laagje water van een paar centimeter en laat het stil worden.","Laat je kind flink wat gemalen peper over het water strooien, tot het vol zwarte puntjes ligt.","Laat je kind eerst een schone, droge vinger in het midden steken. Wat doet de peper?","Doe een druppel afwasmiddel op een schoteltje. Laat je kind de vingertop erin dopen en steek die weer midden in het water.","Kijk hoe de peper in een flits naar de rand vlucht! Raad samen: waarom rent de peper weg?","Spoel het bord om en begin opnieuw met vers water: met zeep erin werkt de truc niet meer."],"ageTips":{"young":"Een driejarige wil de truc steeds opnieuw zien. Zet een paar borden met water en peper klaar, zodat je snel weer kunt toveren, en laat je kind zelf strooien.","old":"Laat je kleuter testen wat nog meer werkt: een vinger met boter, met zout of met shampoo. Wat laat de peper rennen, en wat niet? Vertel daarna: het zeepje breekt het dunne vliesje op het water."},"safety":["Peper prikt in ogen en neus: strooi laag boven het bord en laat je kind niet met peperhanden in de ogen wrijven.","Afwasmiddel hoort niet in de mond: spoel de vinger na elke keer even af onder de kraan."],"say":["Kijk eens, de peper drijft als allemaal kleine bootjes!","Wat denk je dat er gebeurt als je je vinger erin steekt?","Weg! Ze rennen allemaal naar de kant.","Wat zit er nu op je vinger dat er net nog niet op zat?","Wat goed dat je het ook met een schone vinger probeerde. Zo ontdek je het verschil."],"words":["strooien","drijven","wegrennen","rand","midden","zeep","toveren"],"learn":["ontdekken","taal","concentratie"],"tips":["Speel het als goocheltruc met ‘hocus pocus’, en laat je kind de truc daarna zelf aan opa, oma of een vriendje voordoen.","Een wit bord laat de zwarte peper het best zien. Geen peper? Gedroogde oregano of peterselie werkt ook."],"variations":["Visjes en de haai: de peperpuntjes zijn visjes en de zeepvinger is de haai. Waar zwemmen de visjes naartoe?","Tegentruc: leg na het wegrennen een suikerklontje midden in het water. Komt de peper dan juist naar het midden toe?","Zeepbootje: knip een klein bootje van karton met een inkeping achteraan, zet het op het water en druppel afwasmiddel in de inkeping: het vaart vanzelf weg."],"themes":[]},
  {"id":"lavalamp","title":"Lavalamp in een fles","emoji":"🧴","category":"proefjes","summary":"Water met kleurstof, olie en een stukje bruistablet in een fles: kijk hoe de gekleurde bellen op en neer borrelen, net een echte lavalamp.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"plastic-flesjes","note":"doorzichtig, ±500 ml, etiket eraf"},{"id":"water","note":"±125 ml"},{"id":"kleurstof","note":"een paar druppels"},{"id":"olie","note":"±350 ml zonnebloemolie"},{"id":"bruistablet","note":"een half tablet per keer, in stukjes gebroken"},{"id":"dienblad","note":"om op te werken: olie op tafel is glibberig"}],"optional":[{"id":"trechter","note":"om de olie in de fles te gieten"},{"id":"zaklamp","note":"eronder of erachter, voor een echt lampeffect"},{"id":"zout","note":"als je geen bruistablet hebt"}],"steps":["Zet de fles op het dienblad. Giet er ±125 ml water in (tot een kwart) en laat je kind een paar druppels kleurstof toevoegen.","Vul de fles samen verder met olie tot een paar centimeter onder de rand; met een trechter gaat het makkelijker.","Wacht even en kijk: de olie blijft bovenop drijven en het gekleurde water zakt naar de bodem.","Breek een half bruistablet in een paar stukjes en laat je kind er één in de fles gooien.","Kijk: de gekleurde bellen borrelen naar boven en zakken weer naar beneden. Gestopt? Doe er een nieuw stukje in.","Draai de dop er pas op als het bruisen helemaal gestopt is, en bewaar de fles voor een volgende keer."],"ageTips":{"young":"Een driejarige mag het stukje tablet erin gooien; de olie giet jij en de tabletten houd je bij je. Doe telkens een klein stukje, dan is er vaak iets nieuws te zien.","old":"Laat je kleuter voorspellen en testen: bruist een groot stuk tablet langer dan een klein stukje? Tel samen hoe lang de bellen doorgaan en vergelijk."},"safety":["Bruistabletten zijn medicijnen of vitaminen: houd de verpakking zelf vast en berg hem daarna hoog en buiten bereik op.","Olie en kleurstof vlekken, en olie op de vloer is spiegelglad: werk op een dienblad en veeg morsen meteen op met keukenpapier en een sopje.","Draai de dop niet dicht zolang het nog bruist: er bouwt dan druk op in de fles."],"say":["Kijk, de olie en het water willen niet mengen!","Wat denk je dat er gebeurt als het tabletje erin valt?","Ik zie een rode bel naar boven gaan… en weer naar beneden zakken.","Blub, blub, blub! Nog een stukje?","Wat kijk je goed: jij zag als eerste dat het stopte."],"words":["bubbels","olie","omhoog","omlaag","drijven","zakken","bruisen"],"learn":["ontdekken","zintuigen","taal"],"tips":["Gebruik goedkope zonnebloemolie: de fles kun je dagenlang bewaren en steeds opnieuw laten borrelen met een nieuw stukje tablet.","Geen bruistablet? Strooi 1 tl zout in de fles: er zakken oliebolletjes naar beneden die daarna weer omhoog drijven.","Giet de olie na afloop niet door de gootsteen, maar doe hem in een afgesloten fles bij het restafval of lever hem in bij de inzamelplek voor frituurvet."],"variations":["Lichtshow: doe het grote licht uit en schijn met een zaklamp onder of achter de fles.","Regenbooglampen: maak drie kleine flesjes in verschillende kleuren en zet ze naast elkaar voor het raam.","Kleurenmix: druppel later een tweede kleur in de fles. Zakt de druppel door de olie heen, en welke kleur krijgt het water?"],"themes":[]},
  {"id":"dansende-rozijnen","title":"Dansende rozijnen","emoji":"🍇","category":"proefjes","summary":"Gooi rozijnen in een glas bruiswater en kijk hoe ze naar de bodem zakken, weer omhoog zweven en op en neer blijven dansen.","ageMin":3,"ageMax":5,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"durationMinutes":10,"supervision":2,"materials":[{"id":"bruiswater","note":"een vers geopende fles"},{"id":"rozijnen","note":"6-8 stuks"},{"id":"beker","note":"een hoog, doorzichtig glas of plastic beker"}],"optional":[{"id":"water","note":"kraanwater in een tweede glas, om te vergelijken"},{"id":"pasta","note":"stukjes droge spaghetti om ook te laten dansen"}],"steps":["Schenk een hoog glas vol met vers bruiswater en kijk samen naar de belletjes.","Laat je kind vijf tot acht rozijnen één voor één in het glas gooien.","Kijk goed: de rozijnen zakken eerst naar de bodem. Wacht even… daar komen ze weer omhoog!","Bekijk een rozijn van dichtbij: zie je de belletjes die eraan vastplakken? Die tillen hem op als een zwembandje.","Zet een glas kraanwater ernaast en doe daar ook een paar rozijnen in. Wat is het verschil?","Vis de rozijnen er na afloop uit met een lepel. Opeten mag, ze zijn alleen wat zachter geworden."],"ageTips":{"young":"Voor een driejarige is het dansen al spannend genoeg. Houd het bij één glas en zing erbij: op en neer, op en neer!","old":"Laat je kleuter tellen hoeveel rozijnen er tegelijk bovenaan drijven, of kies samen één rozijn en tel hoe vaak hij bovenkomt. Vertel dan: bovenaan knappen de belletjes en zakt hij weer."},"safety":["Gebruik een stevig glas of een doorzichtige plastic beker en zet hem midden op tafel: een omgestoten glas kan breken.","Dweil gemorst bruiswater meteen op: een natte vloer is glad."],"say":["Kijk, de rozijn zakt naar de bodem… en nu komt hij weer omhoog!","Wat zie je allemaal aan de rozijn plakken?","Wat denk je: gaan ze ook dansen in gewoon water?","Op en neer! Op en neer!","Wat kijk je geduldig. Jij zag als eerste dat die kleine rozijn bovenkwam."],"words":["bubbels","omhoog","omlaag","bodem","bovenop","dansen","prik"],"learn":["ontdekken","taal","rekenen"],"tips":["Gebruik een vers geopende fles: hoe meer prik, hoe langer de rozijnen dansen. Na een kwartier is de prik er meestal uit.","Een hoog, smal glas werkt het best: dan hebben de rozijnen een lange dansvloer en zie je alles goed."],"variations":["Dansende spaghetti: breek droge spaghetti in stukjes van 2 cm en kijk of die ook gaan dansen.","Zonder prik: doe 1 tl baking soda in een glas water, giet er een scheutje azijn bij en gooi er rozijnen in.","Rozijnendisco: zet muziek op en dans mee. Gaat de rozijn omhoog, dan sta jij op; zakt hij, dan ga je zitten."],"themes":[]},
  {"id":"tuinkers-eierkoppen","title":"Eierkoppen met tuinkershaar","emoji":"🥚","category":"proefjes","summary":"Teken een gezichtje op een lege eierschaal, zaai er tuinkers in en kijk hoe je eierkop in een week een groene bos haar krijgt.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"eieren","note":"lege schalen van gekookte eitjes, alleen het kapje eraf"},{"id":"watten","note":"een paar wattenbolletjes per ei"},{"id":"tuinkers","note":"een zakje zaadjes"},{"id":"stiften","note":"om een gezichtje te tekenen"},{"id":"eierdoos","note":"als standaard voor de eierkoppen"},{"id":"water"}],"optional":[{"id":"plantenspuit","note":"om de watten vochtig te houden"},{"id":"kinderschaar","note":"kleuters knippen het haar zelf"},{"id":"potgrond","note":"in plaats van watten"}],"steps":["Bewaar een paar lege schalen van gekookte eitjes: tik alleen het kapje eraf, eet het ei op en spoel de schaal om met warm water.","Zet de schalen in de eierdoos en laat je kind er met stiften een gezichtje op tekenen.","Vul elke schaal met wattenbolletjes en maak ze goed nat met 2-3 el water.","Strooi een flinke snuf tuinkerszaadjes op de natte watten en druk ze zachtjes aan.","Zet de eierkoppen op een lichte vensterbank en houd de watten elke dag vochtig.","Kijk elke dag even: na 1-2 dagen zie je kiempjes, na ongeveer een week heeft je eierkop een flinke bos haar.","Knip het haar af en eet het op een boterham met ei of kaas."],"ageTips":{"young":"Een eierschaal is voor een tweejarige erg breekbaar: gebruik dan een vakje van de eierdoos als kopje. Zaadjes strooien en water geven met een theelepel kan je peuter prima zelf.","old":"Laat je kleuter elke dag een tekening van de eierkop maken in een groeiboekje. Hoeveel dagen duurt het tot de eerste blaadjes? En welk kapsel knip je straks?"},"safety":["Ei-allergie in huis? Gebruik dan vakjes van de eierdoos of lege bakjes in plaats van eierschalen.","Werk je met schalen van rauwe eieren, spoel ze dan goed om met heet water en was daarna ieders handen: op rauw ei kunnen bacteriën (salmonella) zitten.","Een kapotte eierschaal heeft scherpe randjes: gooi gebroken schalen meteen weg."],"say":["Kijk, piepkleine zaadjes! Wat zou eruit groeien?","Nat maken. Druppel, druppel!","Ik zie witte worteltjes! Gisteren waren die er nog niet.","Wat zorg je goed voor je eierkop: je geeft hem elke dag water.","Hoe zal jouw eierkop eruitzien met lang haar?"],"words":["zaadje","kiemen","groeien","wortel","blaadje","knippen","haar"],"learn":["ontdekken","fijne-motoriek","creativiteit","taal"],"tips":["Spaar een paar dagen lang de schalen van gekookte eitjes en spoel ze meteen om, dan gaan ze niet ruiken.","Geen watten? Een prop nat keukenpapier of een schepje potgrond werkt net zo goed.","Draai de eierkoppen elke dag een kwartslag: tuinkers groeit naar het licht toe en anders krijgt je eierkop een scheve kuif."],"variations":["Pasen: zet de eierkoppen als groene versiering op de paastafel, met een zelfgemaakt kuikentje erbij.","Kapsalon: strooi de zaadjes alleen in een smalle strook voor een hanenkam, of aan één kant voor een scheiding.","Lente: zaai tuinkers op nat keukenpapier in de vorm van de eerste letter van de naam van je kind."],"themes":["lente","pasen"]},
  {"id":"vogelvoer-dennenappels","title":"Vogelvoer-dennenappels voor bij het raam","emoji":"🐦","category":"proefjes","summary":"Smeer een dennenappel in met pindakaas, rol hem door vogelzaad en hang hem bij het raam: daarna kijk je vanuit binnen wie er komt snoepen.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"dennenappels","note":"grote, open exemplaren, eerder verzameld"},{"id":"pindakaas","note":"liefst zonder zout; bij een pinda-allergie reuzel of vet"},{"id":"vogelzaad","note":"of havermout met ongezouten zaden"},{"id":"touw","note":"±30 cm per dennenappel"},{"id":"ijsstokjes","note":"om mee te smeren"},{"id":"bord","note":"om het vogelzaad op uit te strooien"}],"optional":[{"id":"zip-zakjes","note":"om de dennenappel in het zaad te schudden (minder rommel)"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"wc-rollen","note":"in plaats van een dennenappel"}],"steps":["Knoop een touw van ongeveer 30 cm stevig om de bovenste schubben van de dennenappel. Dat doe jij.","Doe 3-4 el pindakaas in een kommetje en strooi het vogelzaad uit op een bord.","Laat je kind de dennenappel met een ijsstokje insmeren: tussen de schubben mag de pindakaas er lekker dik in.","Rol de dennenappel door het vogelzaad en druk het zaad met je handen goed aan.","Hang hem buiten bij het raam, aan een tak, de balkonrand of een haakje, hoog genoeg voor katten. Dat doe jij.","Ga samen binnen op de uitkijk zitten: welke vogels komen er eten? Tel ze en geef ze een naam."],"ageTips":{"young":"Een tweejarige smeert het liefst met de handen: prima, dat voelt lekker. Doe het zaad in een diepvrieszakje en laat je peuter de dennenappel erin schudden.","old":"Laat je kleuter een turflijst maken: teken een mees, een merel en een mus en zet een streepje bij elke vogel die je ziet. Wie komt er het vaakst?"},"safety":["Pinda-allergie in huis? Gebruik dan reuzel of vet in plaats van pindakaas en was na afloop handen, tafel en spullen goed.","Vogelzaad is niet om te eten: zaden en hele pinda’s kunnen in de luchtpijp schieten. Hele noten en pinda’s zijn niet geschikt voor kinderen onder de 4."],"say":["Smeer, smeer! Helemaal plakkerig!","Hoe voelt de dennenappel: glad of stekelig?","Ik zie dat je pindakaas tussen alle schubben hebt gestopt. Daar smullen de vogels van.","Welke vogel denk je dat als eerste komt eten?","Sst… kijk, daar is een mees! Wat doet hij?"],"words":["dennenappel","plakkerig","smeren","zaadjes","vogel","mees","pikken"],"learn":["fijne-motoriek","zintuigen","ontdekken","taal"],"tips":["Leg een knoeimat of krant neer en trek een oud shirt aan: vet geeft vlekken en vogelzaad rolt overal heen. Met een kruimeldief is het zo opgeruimd.","Geen dennenappels? Smeer een wc-rolletje in, rol het door het zaad en schuif het over een tak of rijg er een touwtje door.","Hang het voer op een plek waar katten niet bij kunnen en vervang het als het gaat schimmelen. Vogels hebben het vooral nodig bij vorst en sneeuw."],"variations":["Vetkoekjes: meng gesmolten vet met vogelzaad, giet het in uitsteekvormpjes op bakpapier, leg er een lusje touw in en laat het opstijven in de koelkast. Het smelten doe jij.","Kerst: hang een paar dennenappels met een strikje als versiering in een boom bij het raam.","Vogelboekje: maak een foto van elke vogel die komt eten en zoek samen de naam op."],"themes":["winter"]},
  {"id":"pasta-rijgen","title":"Pastaketting rijgen","emoji":"📿","category":"motoriek","summary":"Rijg penne of rigatoni aan een touw tot een ketting of armband: goed voor handige vingers én een cadeautje om trots op te zijn.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"pasta","note":"penne of rigatoni: hoe groter het gat, hoe makkelijker"},{"id":"touw","note":"of wol: ±70 cm voor een ketting, ±25 cm voor een armband"},{"id":"plakband","note":"om het puntje van het touw stijf te maken"}],"optional":[{"id":"schoenveter","note":"heeft al een hard puntje: makkelijk voor beginners"},{"id":"pijpenragers","note":"stijf en makkelijk om op te oefenen; puntjes omvouwen"},{"id":"kleurstof","note":"om de pasta vooraf te kleuren (zie tips)"},{"id":"zip-zakjes","note":"om de pasta in te kleuren"}],"steps":["Knip een touw van ±70 cm voor een ketting of ±25 cm voor een armband. Draai plakband strak om één uiteinde: dat is je ‘naald’.","Knoop aan het andere uiteinde een stuk pasta vast, dan glijdt de rest er niet af.","Doe de pasta in een bakje en laat je kind rijgen: puntje in het gat, doorschuiven en de volgende!","Bedenk samen een patroon, bijvoorbeeld penne-rigatoni-penne, of rood-geel-rood als je gekleurde pasta hebt.","Knoop de uiteinden stevig aan elkaar als het touw bijna vol is (dat doe jij) en knip het plakbandpuntje eraf.","Geef de ketting cadeau of hang hem op. Draagt je kind hem zelf, doe hem dan af voor het slapen."],"ageTips":{"young":"Een tweejarige rijgt het makkelijkst met rigatoni op een schoenveter of pijpenrager. Houd jij het touw rechtop vast; je peuter doet de pasta op het puntje en laat hem naar beneden zakken.","old":"Laat je kleuter een patroon bedenken en volhouden, de stukjes tellen of de pasta zelf kleuren. Hang er een hartje of letter van karton aan voor wie de ketting krijgt."},"safety":["Droge pasta past door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij je peuter en ruim gevallen stukjes direct op.","Een ketting kan verstrikt raken (wurggevaar): laat je kind hem nooit zonder toezicht om de nek dragen en doe hem af voor het slapen en bij het klimmen."],"say":["Erin… en doorschuiven! Nog een!","Ik zie dat je het touw goed strak houdt. Zo glijdt de pasta er makkelijk op.","Hoeveel stukjes zitten er al aan je ketting? Zullen we tellen?","Wat komt er nu in jouw patroon: een dunne of een dikke?","Wat heb jij lang volgehouden, wat een geduld!"],"words":["rijgen","gat","door","touw","ketting","patroon","lang","kort"],"learn":["fijne-motoriek","concentratie","rekenen","creativiteit"],"tips":["Gekleurde pasta: schud 200 g pasta met 1 tl azijn en een paar druppels kleurstof in een ritszakje, spreid uit op bakpapier en laat 1-2 uur drogen.","Bewaar een half afgemaakte ketting met de pasta in een ritszakje: morgen gewoon verder rijgen."],"variations":["Moederdag: rijg een ketting voor mama of oma en hang er een hartje van karton aan.","Armband: vijf of zes stukjes op een kort touwtje, snel af en net zo trots om te geven.","Rups: rijg pasta op een pijpenrager, buig hem in een bocht en teken met stift een gezichtje op het eerste stukje.","Kerst: rijg rood en groen gekleurde pasta tot een slinger voor in de kerstboom."],"themes":["moederdag","cadeau"]},
  {"id":"spaghetti-prikken","title":"Spaghetti prikken in een vergiet","emoji":"🍝","category":"motoriek","summary":"Prik droge spaghetti of pijpenragers door de gaatjes van een omgekeerd vergiet en schuif er ontbijtringetjes overheen: een rustig prikspel voor kleine vingers.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"vergiet","note":"omgekeerd op tafel; liefst met gaatjes waar een sliert net door past"},{"id":"pasta","note":"droge spaghetti, in halve slierten gebroken"},{"id":"ontbijtgranen","note":"ontbijtringetjes om over de slierten te schuiven"}],"optional":[{"id":"pijpenragers","note":"zachter en steviger voor dreumesen; puntjes omvouwen"},{"id":"dienblad","note":"onder het vergiet, dan rollen de ringetjes niet weg"}],"steps":["Zet een vergiet ondersteboven op een dienblad of op tafel.","Breek een paar slierten droge spaghetti doormidden en leg ze in een bakje naast het vergiet.","Laat zien hoe je een sliert door een gaatje prikt. Nu jij: hoeveel slierten passen erin?","Geef ontbijtringetjes als het vergiet vol staat, en laat je kind ze één voor één over een sliert schuiven.","Trek alles er weer uit en begin opnieuw: eruit halen is net zo leuk als erin stoppen."],"ageTips":{"young":"Geef een dreumes van 1 liever pijpenragers met omgevouwen puntjes: die breken niet en zijn makkelijker vast te pakken. Prikken en eruit trekken is uitdaging genoeg; de ringetjes komen later.","old":"Een driejarige kan tellen hoeveel ringetjes er op één sliert passen, gekleurde pijpenragers op kleur sorteren of penne over de slierten rijgen. Wie bouwt de hoogste toren van ringetjes?"},"safety":["Droge spaghetti breekt in harde, scherpe stukjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: ruim gebroken stukjes meteen op en blijf erbij.","In pijpenragers zit ijzerdraad met een scherp puntje: vouw beide uiteinden een stukje om.","Ontbijtringetjes mogen opgegeten worden, maar laat je kind dan rechtop zitten en blijf erbij."],"say":["Prik! Nog een!","Ik zie dat je heel goed mikt op dat kleine gaatje.","Waar gaat deze sliert naartoe: bovenop of aan de zijkant?","Wat heb je geduldig geprikt, het vergiet lijkt wel een egel!","Hoe voelt de pijpenrager: zacht of kriebelig?"],"words":["prikken","gaatje","erin","eruit","lang","vol","ringetje","bovenop"],"learn":["fijne-motoriek","concentratie","ontdekken"],"tips":["Zet het vergiet op een dienblad: gevallen ringetjes blijven dan binnen handbereik en rollen niet onder de bank.","Geen vergiet? Prik met een pen gaatjes in een omgekeerde schoenendoos (dat doe jij)."],"variations":["Taart: prik de slierten als kaarsjes in een bal speeldeeg of eetbaar havermoutdeeg en zing ‘Lang zal ze leven’.","Doos: prik grotere gaten in een schoenendoos en laat je kind er rietjes of pijpenragers in steken.","Kleuren: gebruik pijpenragers in verschillende kleuren en zet ze per kleur bij elkaar."],"themes":[]},
  {"id":"wasknijpers","title":"Wasknijper-figuren: leeuw, egel en zon","emoji":"🦁","category":"motoriek","summary":"Knijp wasknijpers op de rand van een papieren bordje tot een leeuw met manen, een egel of een zon: knijpen maakt kleine vingers sterk.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"wasknijpers","note":"10-20 stuks; liefst met een niet te stugge veer"},{"id":"papieren-bordjes","note":"of een rondje karton"},{"id":"stiften","note":"om een gezicht te tekenen"}],"optional":[{"id":"waskrijt","note":"om het bordje geel of oranje te kleuren"},{"id":"karton","note":"voor een egel: knip een druppelvorm uit"},{"id":"bladeren","note":"om tussen de stekels van de egel te knijpen"}],"steps":["Kies samen wat je maakt: een leeuw, een zon of een egel. Teken met stift een gezicht in het midden van het bordje.","Kleur het bordje eventueel geel of oranje met waskrijt. Voor een egel knip je een druppelvorm uit karton (dat doe jij).","Laat zien hoe een knijper werkt: knijpen, openhouden, over de rand schuiven en loslaten.","Knijp samen de knijpers rondom de rand: manen voor de leeuw, stralen voor de zon, stekels op de rug van de egel.","Haal ze er weer af en begin opnieuw, of tel hoeveel knijpers er rondom passen."],"ageTips":{"young":"Voor een tweejarige is een knijper openknijpen echt zwaar werk. Zoek de slapste knijpers uit, houd jij het bordje vast en begin met drie knijpers. Knijpers eraf halen is ook al knap.","old":"Laat je kleuter een kleurpatroon maken (geel, oranje, geel…), tellen hoeveel knijpers er passen of een eigen dier bedenken: een spin met acht poten of een krab met scharen."},"safety":["Knijpers knijpen ook in vingertjes, neusjes en oorlelletjes: laat ze niet aan het gezicht hangen.","Gooi kapotte knijpers meteen weg: het losse veertje is klein en scherp, en alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Knijp… open… en los!","Ik zie dat je duim en je wijsvinger samen hard werken.","Hoeveel stralen heeft jouw zon al?","Wat heb je goed doorgezet: die knijper was stug!","Wat voor dier zou jij nog kunnen maken met knijpers?"],"words":["knijpen","open","dicht","rand","rondom","manen","stekels","stralen"],"learn":["fijne-motoriek","rekenen","creativiteit"],"tips":["Test de knijpers eerst zelf: sommige zijn veel stugger dan andere. Leg de makkelijkste apart voor je kind.","Bewaar bordjes en knijpers samen in een zak: een kant-en-klaar spelletje voor onderweg of bij opa en oma."],"variations":["Herfst: knip een egel uit bruin karton, knijp er stekels op en steek een blaadje achter een van de knijpers.","Zomer: maak een gele zon met knijpers als stralen en hang hem voor het raam.","Kleurenspel: kleur de rand van het bordje in vakjes en zoek een knijper in dezelfde kleur.","Bloem of vis: knijpers als bloemblaadjes rond een hartje, of als vinnen en staart aan een kartonnen vis."],"themes":["herfst","zomer"]},
  {"id":"kleuren-sorteren","title":"Sorteren op kleur in een muffinvorm","emoji":"🌈","category":"motoriek","summary":"Leg in elk vakje van een muffinvorm een gekleurd papiertje en zoek samen uit wat waar hoort: met je handen, een lepel of een knijper.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"muffinvorm","note":"of een eierdoos of losse bakjes"},{"id":"gekleurd-papier","note":"een rondje per vakje, in de kleuren van je spullen"},{"id":"duplo","note":"of andere grote spulletjes in verschillende kleuren"}],"optional":[{"id":"pompons","note":"pas vanaf 3 jaar"},{"id":"doppen","note":"kleine doppen pas vanaf 3 jaar"},{"id":"wasknijpers","note":"als tangetje voor kleuters"},{"id":"lepel","note":"om mee te scheppen"}],"steps":["Knip rondjes gekleurd papier en leg er één onderin elk vakje van de muffinvorm, bijvoorbeeld rood, geel, blauw en groen.","Doe alle spulletjes door elkaar in een kom: duplo, of vanaf 3 jaar ook pompons en doppen.","Pak er samen één uit: welke kleur is dit? Waar woont rood?","Laat je kind alles sorteren met de handen. Gaat dat makkelijk? Probeer dan een lepel of een wasknijper als tangetje.","Kijk samen naar de vakjes: waar zitten de meeste? Gooi alles terug in de kom en begin opnieuw."],"ageTips":{"young":"Begin bij een tweejarige met twee kleuren en grote spullen, en leg in elk vakje alvast één voorbeeld. Benoem steeds de kleur: rood! Nog een rode!","old":"Laat je kleuter sorteren met een wasknijper als tang, of op twee dingen tegelijk: rood én groot. Tel daarna per vakje: van welke kleur heb je er het meest?"},"safety":["Pompons, kleine doppen en kralen passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Geef je peuter duplo of andere grote spullen.","Tel na afloop of alle kleine spulletjes terug zijn in het bakje, zeker als er een jonger broertje of zusje rondkruipt."],"say":["Rood! Waar woont rood?","Ik zie dat je alle gele blokjes al bij elkaar hebt gezet.","Hoe weet jij dat deze bij blauw hoort?","Van welke kleur hebben we de meeste, denk je?","Met een wasknijper pakken is lastig, en jij blijft het proberen!"],"words":["rood","geel","blauw","groen","hetzelfde","sorteren","meer","minder"],"learn":["rekenen","fijne-motoriek","taal","concentratie"],"tips":["Passen je spullen niet in de vakjes? Sorteer dan in kommen of schoenendozen met een gekleurd vel erin.","Bewaar de muffinvorm met de papiertjes en spulletjes in een zak: een snel spelletje voor een regenachtige ochtend."],"variations":["Op maat: sorteer groot en klein, of zwaar en licht, in twee bakken.","Herfst: sorteer verzamelde blaadjes op kleur in bakjes: groen, geel, oranje en bruin.","Opruimspel: laat je kind speelgoed per kleur terugbrengen naar de bakken."],"themes":[]},
  {"id":"plakbandweb","title":"Redden uit het plakbandweb","emoji":"🕸️","category":"motoriek","summary":"Plak schilderstape kriskras over een wasmand vol speelgoed en laat je kind de gevangen diertjes één voor één bevrijden.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"schilderstape","note":"of plakband, één rol"},{"id":"wasmand","note":"of een doos zonder deksel"},{"id":"klein-speelgoed","note":"of knuffels; voor kinderen onder de 3 groter dan een wc-rolletje"}],"optional":[{"id":"wasknijpers","note":"als vistang voor kleuters"},{"id":"pijpenragers","note":"om een spin van te buigen"}],"steps":["Leg speelgoed of knuffels onderin een wasmand of doos.","Plak lange stroken schilderstape kriskras over de opening, van rand naar rand. Laat genoeg ruimte voor een kinderhand.","Vertel erbij: oh nee, de diertjes zitten gevangen in het web! Wie helpt ze eruit?","Laat je kind de diertjes tussen de stroken door eruit halen, of de tape lostrekken: allebei goed.","Zet de geredde diertjes op een rij en tel samen: hoeveel zijn er al vrij?","Prop de tape samen tot een grote bal en gooi hem in de prullenbak."],"ageTips":{"young":"Plak voor een dreumes maar een paar stroken, ver uit elkaar, en gebruik knuffels of grote blokken die makkelijk te pakken zijn. Lostrekken is voor je dreumes net zo leuk als redden.","old":"Maak het web dichter en laat je kleuter vissen met een wasknijper als tang, zonder de tape te raken. Of speel tegen de klok: hoeveel diertjes red je in één minuut?"},"safety":["Propjes tape belanden bij een dreumes snel in de mond (verstikkingsgevaar): gooi losgetrokken stroken direct weg.","Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: verstop voor je dreumes of peuter alleen grote speeltjes en knuffels."],"say":["Trek! Daar is de eend!","Wie zit er nog gevangen in het web?","Ik zie dat je je hand heel voorzichtig tussen de stroken door steekt.","Hoe voelt de tape: plakkerig of glad?","Wat ben jij een goede redder: je blijft het gewoon proberen!"],"words":["plakkerig","trekken","onder","tussen","door","vast","los","bevrijden"],"learn":["fijne-motoriek","concentratie","taal","ontdekken"],"tips":["Schilderstape is fijner dan plakband: het plakt minder hard aan kleine vingers en trekt makkelijk los van de wasmand.","Geen wasmand? Plak het web tussen de poten van een stoel of over een la."],"variations":["Halloween: buig een spin van een pijpenrager, zet hem op het web en red de diertjes voor hij terugkomt!","Muffinvorm-web (vanaf 3 jaar): plak tape over de vakjes van een muffinvorm met in elk vakje een kleine verrassing.","Garage: zet speelgoedautootjes in een doos en laat ze door het web naar buiten rijden."],"themes":["halloween"]},
  {"id":"plakband-lostrekken","title":"Plakbandjes lostrekken","emoji":"✋","category":"motoriek","summary":"Plak stroken schilderstape op tafel, raam of vloer en laat je kind ze lostrekken: simpel, stil en heerlijk voor kleine vingertjes.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":10,"supervision":2,"materials":[{"id":"schilderstape","note":"liefst in een paar kleuren"}],"optional":[{"id":"papier","note":"om de losgetrokken stroken op te plakken"},{"id":"stiften","note":"om de tape in te kleuren of figuurtjes op te tekenen"},{"id":"speelgoedautos","note":"om over een tapeweg te laten rijden"}],"steps":["Plak 10-15 stroken schilderstape op het tafelblad, het raam of de vloer: rechte lijnen, kruisjes of een zonnetje.","Vouw aan elke strook een puntje om, plakkant op plakkant: zo kan je kind het makkelijk vastpakken.","Laat zien hoe je aan het puntje trekt. Nu jij!","Benoem wat je ziet: een lange gele strook, een korte blauwe, een kruisje.","Plak de losgetrokken stroken samen op een vel papier: een kunstwerk van tape."],"ageTips":{"young":"Plak voor een dreumes van 1 een paar korte, brede stroken laag op de vloer of het raam, met een groot omgevouwen puntje. Trek de eerste samen los.","old":"Een driejarige kan in een vaste volgorde lostrekken (eerst alle rode), zelf stukjes tape afscheuren en opplakken, of eerst met een autootje over de tapeweg rijden."},"safety":["Een propje tape is voor een dreumes zo in de mond (verstikkingsgevaar): verzamel losgetrokken stroken meteen op een vel papier of in de prullenbak.","Plak geen tape in de buurt van stopcontacten en snoeren: daar wil je je kind niet laten peuteren en trekken."],"say":["Trek! Los!","Ik zie een lange gele streep. Kun jij hem vinden?","Hoor je dat? Krrrt, zegt de tape.","Hoe voelt de plakkant aan je vinger?","Wat zet jij goed door, die laatste zat echt vast!"],"words":["trekken","los","plakkerig","lang","kort","streep","kruis","puntje"],"learn":["fijne-motoriek","taal","zintuigen","concentratie"],"tips":["Haal de tape dezelfde dag weg van ramen, deuren en lak: hoe langer hij zit, hoe vaster hij gaat plakken.","Geen gekleurde tape? Kleur gewone schilderstape met stift, dan kun je toch kleuren benoemen."],"variations":["Tapeweg: plak een weg op de vloer, rijd er met autootjes over en trek hem daarna samen los.","Knuffelredding: plak een knuffel ‘vast’ op tafel onder een paar stroken en laat je kind hem bevrijden.","Raamkunst: plak een huis of zon op het raam en trek de stroken er een voor een weer af."],"themes":[]},
  {"id":"rijgkaarten","title":"Rijgkaarten maken","emoji":"🧵","category":"motoriek","summary":"Knip een vorm uit karton, pons er gaatjes in en rijg er een veter doorheen: een rustig rijgspel dat je steeds opnieuw kunt doen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"karton","note":"bijv. van een cornflakesdoos: dun karton is makkelijk te ponsen"},{"id":"perforator","note":"voor de gaatjes"},{"id":"schoenveter","note":"of touw van ±60 cm met plakband om het puntje"},{"id":"stiften","note":"om de vorm te tekenen en te versieren"}],"optional":[{"id":"touw","note":"of wol, als je geen veter hebt"},{"id":"plakband","note":"om het puntje van het touw stijf te maken"},{"id":"stickers","note":"om de kaart te versieren"},{"id":"kinderschaar","note":"voor kleuters die zelf willen knippen"}],"steps":["Teken een grote, eenvoudige vorm op het karton, zoals een appel, vis, hart of auto, en knip hem uit (dat doe jij).","Pons rondom gaatjes in de rand, ongeveer 2-3 cm uit elkaar. Laat je kind ook eens ponsen: met twee handen flink drukken!","Laat je kind de vorm versieren met stift of stickers.","Knoop de veter vast aan het eerste gaatje. Gebruik je touw? Draai dan plakband strak om het losse puntje.","Rijg samen: door een gaatje naar achteren, door het volgende weer naar voren. Zeg erbij: erin… en eruit!","Trek de veter eruit als je helemaal rond bent en begin opnieuw, of knoop hem vast en hang de kaart op."],"ageTips":{"young":"Maak voor een driejarige maar 6-8 gaten en gebruik een veter met een hard puntje. Het maakt niet uit hoe je kind rijgt: kriskras is ook rijgen.","old":"Laat je kleuter zelf de vorm tekenen, uitknippen met een kinderschaar (jij knipt de lastige stukjes) en ponsen. Of nummer de gaatjes en rijg ze in de goede volgorde, net als verbind-de-stippen."},"safety":["Veters en touw kunnen om de nek verstrikt raken (wurggevaar): houd ze kort, hooguit ±60 cm, en berg ze op na het spelen.","De rondjes uit de perforator zijn klein: veeg ze op als er een broertje of zusje onder de 3 rondkruipt. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Erin… en eruit!","Welk gaatje komt nu, denk je?","Ik zie dat je de veter helemaal doortrekt tot hij strak zit.","Wat werk je geconcentreerd: je bent al halverwege de vis!","Voel je hoe de veter door het gaatje glijdt?"],"words":["rijgen","gaatje","voor","achter","door","rondom","veter","strak"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Plak een strook plakband over de rand voordat je ponst: dan scheuren de gaatjes minder snel uit.","Gebruik de voorkant van een oude verpakking of ansichtkaart: dan staat er meteen een vrolijk plaatje op."],"variations":["Papieren bordje: pons gaatjes rondom en rijg er een zon met stralen of een spinnenweb van.","Herfst: knip een groot blad, een appel of een paddenstoel uit en rijg met bruin of oranje touw.","Kerst: knip een kerstboom uit en rijg er een rood lint doorheen als slinger."],"themes":[]},
  {"id":"pijpenrager-figuurtjes","title":"Pijpenrager-figuurtjes en ringen","emoji":"🐛","category":"motoriek","summary":"Buig, draai en krul pijpenragers tot ringen, brilletjes en beestjes en rijg er grote kralen op: lekker frunniken voor handige handjes.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":20,"supervision":2,"materials":[{"id":"pijpenragers","note":"een bosje in verschillende kleuren"},{"id":"kralen","note":"grote houten kralen met een flink gat"}],"optional":[{"id":"pasta","note":"penne om te rijgen, als je geen kralen hebt"},{"id":"rietjes","note":"in stukjes geknipt om te rijgen"},{"id":"schaar","note":"een oude, om pijpenragers door te knippen"}],"steps":["Vouw de puntjes van elke pijpenrager een klein stukje om, zodat het ijzerdraadje niet prikt. Knip er een paar doormidden (dat doe jij).","Laat je kind eerst vrij buigen, draaien en krullen. Wat wordt het: een slang, een slak of een bloem?","Maak samen een ring: draai een halve pijpenrager om de vinger van je kind en draai de uiteinden in elkaar.","Rijg grote kralen op een pijpenrager. Buig het ene eind om, dan glijden ze er niet af.","Buig de pijpenrager met kralen tot een rups of armband, of draai vier halve pijpenragers in het midden samen tot een spin met acht poten.","Bewaar de figuurtjes in een doosje: morgen buig je ze gewoon om tot iets nieuws."],"ageTips":{"young":"Voor een driejarige zijn halve pijpenragers handiger dan hele. Kies kralen met grote gaten en laat het buigen vooral vrij: een kronkel is ook een kunstwerk.","old":"Laat je kleuter een brilletje maken: twee rondjes om een stift gedraaid, een bruggetje ertussen en pootjes voor achter de oren. Of buig samen letters en cijfers: welke letter lukt jou?"},"safety":["In pijpenragers zit ijzerdraad met scherpe puntjes: vouw alle uiteinden om, zeker bij een ring of brilletje (vingers en ogen).","Kralen passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Berg ze hoog op als er jongere kinderen in huis zijn."],"say":["Draai, draai, draai… een krul!","Wat kun jij van deze kronkel maken?","Ik zie dat je de kraal precies over het puntje schuift.","Hoe voelt een pijpenrager: zacht of kriebelig?","Wat heb je lang geprobeerd, en nu staat je spin op acht poten!"],"words":["buigen","draaien","krul","rond","recht","kronkel","rijgen","kriebelig"],"learn":["fijne-motoriek","creativiteit","concentratie"],"tips":["Pijpenragers gaan lang mee: buig ze na het spelen recht en bewaar ze met de kralen in een potje.","Geen kralen? Rijg stukjes rietje of penne: licht en makkelijk, en het gat is lekker groot."],"variations":["Kerst: draai een rode en een witte pijpenrager in elkaar en buig er een zuurstok of ster van voor in de boom.","Bloemenperk: buig bloemen met rondjes als blaadjes en prik ze in een bal speeldeeg.","Pasen: buig een paashaas met lange oren of een kuikentje en zet het in een eierdoos."],"themes":[]},
  {"id":"was-ophangen","title":"De was ophangen","emoji":"🧦","category":"motoriek","summary":"Span een waslijn tussen twee stoelen en hang samen sokjes en poppenkleren op met wasknijpers: knijpen, paren zoeken en tellen in één.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"touw","note":"±1,5 meter, als waslijn"},{"id":"stoelen","note":"twee, ruim een meter uit elkaar"},{"id":"wasknijpers","note":"10-20 stuks"},{"id":"sokken","note":"of poppenkleertjes, washandjes en kleine doekjes"}],"optional":[{"id":"wasmand","note":"voor de schone ‘was’"},{"id":"poppen","note":"om na het ophangen weer aan te kleden"}],"steps":["Zet twee stoelen ruim een meter uit elkaar en knoop een touw strak van stoelpoot naar stoelpoot, net onder de zitting: laag genoeg om bij te kunnen.","Doe de ‘was’ in een wasmand en zet de knijpers in een bakje ernaast.","Laat zien hoe het werkt: sok over het touw, knijper erop. Nu jij!","Zoek samen de paren: waar is de andere sok met streepjes? Hang ze naast elkaar.","Hang de was op kleur of van klein naar groot, en tel hoeveel knijpers je nodig hebt.","Haal alles eraf als de was ‘droog’ is, vouw samen op en ruim het touw meteen weg."],"ageTips":{"young":"Geef een tweejarige grote washandjes of doekjes en de slapste knijpers, en hang jij het eerste stuk op. Alleen over het touw hangen, zonder knijper, is ook al goed.","old":"Laat je kleuter in een patroon ophangen (sok, washandje, sok…), paren zoeken met de ogen dicht door alleen te voelen, of een poppenwasserette beginnen met een prijslijst."},"safety":["Een gespannen touw is een wurg- en struikelgevaar: hang het laag, niet in een looproute, en haal het direct weg na het spelen.","Knijpers knijpen ook in vingertjes en oorlelletjes: laat ze niet aan neus, oren of lippen hangen."],"say":["Sok… knijper… vast!","Waar is de andere sok met stippen?","Ik zie dat je de knijper helemaal openhoudt voor je hem loslaat.","Welke sok is het grootst: die van papa of die van jou?","Wat heb jij hard gewerkt, de hele was hangt!"],"words":["ophangen","knijpen","paar","hetzelfde","groot","klein","waslijn","eraf"],"learn":["fijne-motoriek","rekenen","taal"],"tips":["Echt helpen kan ook: laat je kind na de echte was sokken en washandjes aangeven of zelf aan het droogrek hangen.","Gebruik oude sokken van het hele gezin: grote en kleine door elkaar maken sorteren en vergelijken extra leuk."],"variations":["Poppenwas: was eerst poppenkleertjes in een sopje (dat wordt wel nat) en hang ze dan op.","Kunstlijn: hang de tekeningen van deze week aan de lijn, als een echte tentoonstelling.","Kleurenlijn: hang eerst alleen rode dingen op, dan alleen blauwe."],"themes":[]},
  {"id":"uitpakfeest","title":"Uitpakfeest: pakjes openscheuren","emoji":"🎁","category":"motoriek","summary":"Pak bekend speelgoed in met krant en plakband en laat je kind alles openscheuren: een feestje vol verrassingen en een goede oefening voor pakjesavond.","ageMin":1,"ageMax":3,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"klein-speelgoed","note":"of knuffels en blokken die je kind al kent; groter dan een wc-rolletje"},{"id":"kranten","note":"of inpakpapier, keukenpapier of oude tekeningen"},{"id":"plakband","note":"hoe meer plakband, hoe spannender"}],"optional":[{"id":"dozen","note":"een doosje in een doos maakt het extra spannend"},{"id":"stoffen-tas","note":"als ‘zak van Sinterklaas’"},{"id":"wasmand","note":"om het papier in te mikken"},{"id":"muziek","note":"voor het pakjesspel"}],"steps":["Pak 5-8 bekende speeltjes in met krant of papier. Varieer: één los gevouwen, één met veel plakband, één in een doosje.","Leg de pakjes in een zak of wasmand en ga er samen bij zitten.","Laat je kind een pakje kiezen. Voel en schud eerst: wat zou erin zitten?","Scheur een klein randje los als je kind niet weet waar te beginnen, en laat de rest zelf doen.","Vier elke vondst: daar is beer! Speel er even mee voordat het volgende pakje aan de beurt is.","Prop het papier samen tot ballen en mik ze in de wasmand: opruimen is ook een spel."],"ageTips":{"young":"Pak voor een dreumes van 1 losjes in met één laag zacht papier zonder plakband, of stop het speeltje in een papieren zakje. Scheur alvast een beginnetje.","old":"Een driejarige kan raden wat erin zit door te voelen, de pakjes tellen en zelf een pakje inpakken voor een knuffel of voor jou. Of speel het pakjesspel: uitpakken zolang de muziek speelt."},"safety":["Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: pak alleen grote speeltjes in.","Ruim snippers papier en propjes plakband meteen op: een dreumes stopt ze graag in de mond.","Pak niet in met plastic zakken of huishoudfolie: gevaarlijk als het over neus en mond komt."],"say":["Scheur! Wat is het?","Wat zou erin zitten? Schud maar eens.","Ik hoor iets rammelen… jij ook?","Hoe voelt het pakje: zacht, hard of rond?","Wat zoek je slim naar een randje om te beginnen!"],"words":["uitpakken","scheuren","pakje","verrassing","zacht","hard","rammelen","open"],"learn":["fijne-motoriek","zintuigen","taal","samen"],"tips":["Pak in terwijl je kind slaapt, of laat je kind juist meehelpen door stukjes plakband aan te geven.","Oude kranten, folders en tekeningen zijn prima inpakpapier, en dezelfde speeltjes kun je steeds opnieuw inpakken."],"variations":["Sinterklaas: stop de pakjes in een kussensloop als zak van Sinterklaas, zing een liedje en oefen voor pakjesavond.","Kerst: leg de pakjes onder de kerstboom en pak er samen één per dag uit.","Verjaardag: laat een knuffel jarig zijn: pakjes uitpakken, ‘dank je wel’ zeggen en samen zingen.","Lagenpakje: pak een speeltje in, en dat pakje weer, en weer: hoeveel lagen kom je tegen?"],"themes":["sinterklaas","kerst","verjaardag"]},
  {"id":"stickers-op-lijnen","title":"Stickers plakken op lijnen","emoji":"⭐","category":"motoriek","summary":"Jij tekent lijnen, je kind plakt er stickers op: sticker na sticker langs een golf, een zigzag of de eerste letter van de naam.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":15,"supervision":2,"materials":[{"id":"stickers","note":"ronde stippenstickers werken het best"},{"id":"papier","note":"A4 of groter"},{"id":"stiften","note":"een dikke, donkere stift voor de lijnen"}],"optional":[{"id":"groot-papier","note":"voor lange lijnen op tafel of de vloer"},{"id":"schilderstape","note":"om het vel vast te plakken"}],"steps":["Teken met een dikke stift een paar lijnen op een vel: een rechte, een golf, een zigzag en een grote cirkel.","Plak het vel met schilderstape vast op tafel, dan schuift het niet weg.","Trek bij het stickervel alvast het restpapier rond de stickers weg: dan steken ze uit en zijn ze makkelijker te pakken.","Laat zien hoe je een sticker met duim en wijsvinger lostrekt en precies op de lijn plakt.","Volg samen de lijn, sticker na sticker, als stapstenen. Waar gaat de golf naartoe?","Zet de datum op het vel en bewaar het: over een paar maanden zie je hoeveel preciezer je kind plakt."],"ageTips":{"young":"Begin bij een tweejarige met één korte, dikke rechte lijn en grote stickers. Plakt je peuter ernaast? Prima: het gaat om het lostrekken en plakken.","old":"Teken voor je kleuter de eerste letter van de naam, cijfers of een doolhof en plak in een patroon (rood, geel, rood…). Hoeveel stickers passen er op de cirkel?"},"safety":["Stickers en snippers restpapier zijn klein en blijven makkelijk plakken in een mond of keel: blijf bij je peuter en ruim losse stickers direct op."],"say":["Plak! Nog een!","Ik zie dat je precies op de golf plakt.","Waar gaat de lijn naartoe: omhoog of omlaag?","Hoeveel stickers passen er op de cirkel, denk je?","Wat kijk je goed waar je plakt, je neemt echt de tijd."],"words":["lijn","golf","zigzag","rondje","op","naast","omhoog","omlaag"],"learn":["fijne-motoriek","concentratie","rekenen","taal"],"tips":["Ronde stippenstickers vind je goedkoop in de kantoorboekhandel en ze zijn perfect voor kleine vingers.","Geen stickers? Teken stipjes op stukjes schilderstape en laat je kind die op de lijnen plakken."],"variations":["Kerst: teken een kerstboom en plak stickers als ballen langs de takken.","Herfst: teken een kale boom en plak gele en oranje stickers als blaadjes.","Stickerweg: teken een lange slingerweg op groot papier, plak hem vol en laat er daarna een autootje over rijden."],"themes":[]},
  {"id":"rammelaars","title":"Rammelaars maken van lege flesjes","emoji":"🎶","category":"muziek","summary":"Vul lege flesjes met rijst of pasta, plak de dop goed dicht en ontdek samen hoe elke vulling anders klinkt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"plastic-flesjes","note":"kleine flesjes met dop, vanbinnen goed droog"},{"id":"rijst","note":"2-3 el per flesje"},{"id":"pasta","note":"een handje penne of macaroni"},{"id":"ducttape","note":"om de dop rondom dicht te plakken"}],"optional":[{"id":"trechter","note":"om te vullen zonder te morsen"},{"id":"stickers","note":"om te versieren"},{"id":"touw","note":"korte lintjes (max. 15 cm) om de flessenhals, voor een feestelijk tintje"}],"steps":["Spoel de flesjes om en laat ze helemaal drogen, anders plakt de vulling aan de binnenkant.","Zet kommetjes met rijst en pasta klaar en laat je kind met een lepel en een trechter de flesjes vullen. Een kwart vol is genoeg.","Draai de dop er stevig op en plak hem rondom dicht met een paar lagen ducttape. Dat doe jij.","Schud samen: hoe klinkt rijst en hoe klinkt pasta? Welke klinkt hard en welke zacht?","Versier de flesjes met stickers en zet een liedje op: schud mee op de maat!","Controleer de flesjes voor elk gebruik op scheurtjes en een losse dop, en bewaar ze bij het speelgoed."],"ageTips":{"young":"Een dreumes vult nog niet zelf: maak de rammelaars vooraf en laat je kind vooral schudden, rollen en luisteren. In een doorzichtig flesje zie je de rijst ook nog dansen.","old":"Laat je kleuter raden wat erin zit door alleen te luisteren: plak een paar flesjes helemaal af met tape. Of zet ze op een rij van zacht naar hard."},"safety":["Rijst, pasta en de dop zelf zijn te klein voor kinderen onder de 3 (alles wat door een wc-rolletje past): plak de dop rondom vast en vul de flesjes zelf als je dreumes alles in de mond stopt.","Controleer de rammelaar voor elk gebruik op scheurtjes en een losse dop, en gooi een kapot flesje meteen weg.","Gebruik alleen plastic flesjes, geen glazen potjes: die breken als ze vallen."],"say":["Schud, schud! Hoor je dat?","Hoe klinkt de rijst? En hoe klinkt de pasta?","Wat denk je: welke klinkt het hardst?","Ik hoor dat je heel zachtjes schudt… en nu heel hard!","Wat schud je goed op de maat mee!"],"words":["schudden","hard","zacht","snel","langzaam","rammelen","luisteren"],"learn":["zintuigen","fijne-motoriek","ontdekken"],"tips":["Kleine flesjes van drinkyoghurt of sap passen het best in kleine handjes.","Vul de flesjes boven een dienblad of grote bak: gemorste rijst schud je zo terug in het kommetje."],"variations":["Carnaval: maak een hele rammelband en loop schuddend in optocht door de kamer.","Koningsdag: versier de flesjes met oranje en rood-wit-blauwe tape en lintjes.","Geluidsmemory: maak steeds twee flesjes met dezelfde vulling en plak ze af. Welke twee klinken hetzelfde?"],"themes":["carnaval","koningsdag"]},
  {"id":"pannenorkest","title":"Pannenorkest en dozentrommel","emoji":"🥁","category":"muziek","summary":"Pannen, deksels en een doos worden een complete band: trommel samen hard en zacht, snel en langzaam, en ontdek hoe alles anders klinkt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"pan","note":"een paar pannen en deksels, koud uit de kast"},{"id":"lepel","note":"houten lepels als trommelstokken"},{"id":"dozen","note":"een stevige doos als trommel"}],"optional":[{"id":"muziek","note":"om op mee te spelen"},{"id":"plastic-bekers","note":"omgekeerd klinken ze weer anders"}],"steps":["Zet een paar pannen, deksels en een stevige doos ondersteboven op de vloer en geef je kind twee houten lepels.","Ontdek samen: hoe klinkt de grote pan, en hoe klinkt het kleine deksel? En de doos?","Speel eerst hard en daarna heel zacht, als een muisje. Dan snel als regen en langzaam als een olifant.","Speel om de beurt: jij tikt een ritme (tik-tik-boem) en je kind speelt het na. Daarna mag je kind voorspelen.","Zet een liedje op en speel samen mee. Stopt de muziek? Dan stoppen jullie ook!","Ruim samen op door alles op te stapelen: past het kleine deksel op de grote pan?"],"ageTips":{"young":"Een dreumes slaat eerst vooral hard: geniet ervan en doe mee. Houten lepels zijn lichter en zachter dan metalen, en ondersteboven op de vloer staan de pannen stevig.","old":"Laat je kleuter dirigent zijn: armen omhoog is hard spelen, armen omlaag is zacht. Of trommel de lettergrepen van ieders naam: Sa-ra, Bram, Mo-ham-med."},"safety":["Gebruik alleen koude pannen uit de kast, nooit van het fornuis, en houd glazen deksels erbuiten: die kunnen breken.","Een metalen pan klinkt heel hard voor kleine oortjes: speel niet vlak bij het hoofd en wissel af met de zachtere doos."],"say":["Boem! Boem! Hoor je dat?","Welke klinkt het hardst: de pan of de doos?","Kun je ook heel zachtjes spelen, als een muisje?","Ik hoor dat je precies mijn ritme nadoet: tik-tik-boem!","Wat blijf je goed op de maat, ook als het liedje sneller gaat."],"words":["hard","zacht","snel","langzaam","boem","trommel","stil"],"learn":["zintuigen","samen","grove-motoriek","taal"],"tips":["Leg een oude handdoek of deken onder de pannen: dat dempt het geluid voor de buren en spaart je vloer.","Een kastje op kindhoogte met plastic bakjes, een pan en houten lepels is een gratis muziekhoek."],"variations":["Sinterklaas: tik met zachte lepeltjes het paard op het dak na op een doos en zing ‘Hoor de wind waait door de bomen’.","Onweer: begin met tikken met één vinger, dan twee, dan de hele hand, en eindig met een donderslag op de pan.","Fanfare: marcheer met een pan en een lepel door de kamer, en wissel om de beurt van instrument."],"themes":[]},
  {"id":"doosgitaar","title":"Gitaar van een doos","emoji":"🎸","category":"muziek","summary":"Span elastiekjes om een open doos, plak er een koker aan als hals en tokkel: ontdek samen welke snaar hoog en welke laag klinkt.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"dozen","note":"een stevige doos zonder deksel, bijv. een schoenendoos"},{"id":"elastiekjes","note":"4-6 stuks, liefst dikke én dunne"},{"id":"wc-rollen","note":"een keukenrolkoker als hals"},{"id":"ducttape","note":"om de hals vast te plakken"}],"optional":[{"id":"potlood","note":"als ‘brug’ onder de elastiekjes: dan klinkt het luider"},{"id":"stiften","note":"om te versieren"},{"id":"stickers"}],"steps":["Plak een keukenrolkoker met ducttape tegen de korte kant van de doos: dat is de hals van je gitaar.","Span 4-6 elastiekjes in de lengte om de open doos, dik en dun door elkaar. Dat doe jij.","Schuif een potlood dwars onder de elastiekjes, vlak bij één rand: dan klinkt je gitaar luider.","Tokkel samen: klinkt een dik elastiek hoog of laag? En een dun?","Versier de gitaar met stiften of stickers en geef een concertje met je lievelingsliedje.","Bewaar de gitaar hoog op de kast: losse elastiekjes zijn gevaarlijk voor kleine broertjes of zusjes."],"ageTips":{"young":"Voor een driejarige is elastiekjes spannen te lastig en ze schieten snel weg. Span ze zelf en laat je kind tokkelen en plukken. Benoem: hoog, laag, hard, zacht.","old":"Laat je kleuter de elastiekjes ordenen van laag naar hoog, of ontdekken wat er gebeurt als je een elastiek strakker trekt. Lukt het om samen ‘Vader Jacob’ te tokkelen?"},"safety":["Elastiekjes kunnen terugschieten in de ogen: span ze zelf en laat je kind tokkelen zonder ze ver uit te rekken.","Elastiekjes zijn klein en passen door een wc-rolletje: bewaar de gitaar en losse elastiekjes buiten bereik van kinderen onder de 3.","Gooi een uitgedroogd of geknapt elastiekje meteen weg en vervang het."],"say":["Tok! Hoor je dat?","Welke klinkt hoger: het dikke of het dunne elastiek?","Wat gebeurt er als je het elastiek strakker trekt?","Ik zie het elastiek trillen. Voel je het ook met je vinger?","Wat tokkel je geduldig, alle elastiekjes om de beurt."],"words":["tokkelen","trillen","hoog","laag","strak","slap","dik","dun"],"learn":["zintuigen","ontdekken","fijne-motoriek","creativiteit"],"tips":["Een tissuedoos met een gat in het midden is al een kant-en-klare gitaar: span de elastiekjes over het gat.","Een stevige doos klinkt beter dan dun karton: een schoenendoos werkt prima, een cornflakesdoos zakt in."],"variations":["Klankproef: span hetzelfde elastiek om een plastic bakje, een doos en een pan. Welke klinkt het hardst?","Bandje: speel samen met de rammelaars en het pannenorkest en geef een concert voor de knuffels.","Mini-harp: span elastiekjes over een leeg boterkuipje en tokkel met één vinger een slaapliedje."],"themes":[]},
  {"id":"regenstok","title":"Regenstok maken","emoji":"☔","category":"muziek","summary":"Draai aluminiumfolie in een koker, doe er rijst in en plak hem dicht: als je de stok langzaam omdraait, hoor je het zachtjes regenen.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"wc-rollen","note":"een keukenrolkoker, of twee kokers aan elkaar geplakt"},{"id":"aluminiumfolie","note":"2 vellen van ±50 cm"},{"id":"rijst","note":"±3 el"},{"id":"karton","note":"voor twee rondjes om de uiteinden dicht te maken"},{"id":"ducttape","note":"of andere stevige tape"}],"optional":[{"id":"trechter","note":"om de rijst erin te gieten"},{"id":"stiften","note":"om te versieren"},{"id":"stickers"}],"steps":["Trek op karton een rondje om de opening van de koker, knip het iets groter uit en plak er één kant mee dicht. Dat doe jij.","Scheur twee lange vellen aluminiumfolie af en laat je kind ze tot lange slierten draaien en kreukelen.","Draai de slierten tot een spiraal, als een veer, en duw ze in de koker: dat worden trapjes waar de rijst langs valt.","Laat je kind ±3 el rijst in de koker scheppen; met een trechter gaat het makkelijker.","Plak de andere kant dicht met een tweede rondje karton en een paar lagen tape, helemaal rondom.","Versier de regenstok met stiften of stickers en draai hem langzaam om: hoor je de regen?"],"ageTips":{"young":"Een driejarige kan prima folie kreukelen en rijst scheppen. Het dichtplakken doe jij; daarna mag je kind vooral luisteren: langzaam draaien is motregen, snel is een stortbui.","old":"Laat je kleuter testen: hoe klinkt de stok met rijst, met pasta of met linzen? En met meer of minder folie? Maak er twee en vergelijk."},"safety":["Plak de uiteinden met meerdere lagen tape dicht en controleer ze regelmatig: losse rijst is voor kinderen onder de 3 een verstikkingsgevaar.","Geef de regenstok niet aan jongere broertjes of zusjes die erop bijten: het karton wordt dan zacht en scheurt open."],"say":["Ssst… hoor je de regen?","Wat gebeurt er als je hem heel langzaam omdraait? En heel snel?","Ik hoor eerst zachte druppels en daarna een hele bui!","Wat heb je die folie goed gedraaid: het lijkt wel een slang.","Is het nu motregen of een onweersbui?"],"words":["regen","druppels","kreukelen","draaien","zachtjes","omdraaien","luisteren"],"learn":["fijne-motoriek","zintuigen","concentratie"],"tips":["Hoe langer de koker, hoe langer het regent: plak twee of drie kokers met tape aan elkaar.","Geen trechter? Rol een vel papier tot een puntzak en knip het puntje eraf."],"variations":["Herfst: versier de regenstok met gescheurde bladeren of paraplu’s en speel er een herfstbui mee.","Weerverhaal: vertel over de zon, een wolkje en een bui, en laat je kind op het juiste moment de regen maken.","Liedje: zing ‘Het regent, het zegent’ en laat de regenstok meespelen."],"themes":[]},
  {"id":"danslinten","title":"Danslinten maken","emoji":"💃","category":"muziek","summary":"Maak zwierige linten van crêpepapier aan een handvat en dans op muziek: zwaai rondjes, golven en slingers door de kamer.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"crepepapier","note":"of lint, stroken van ±3 cm breed en 50 cm lang"},{"id":"wc-rollen","note":"als handvat (of een ijsstokje)"},{"id":"plakband","note":"om de stroken vast te maken"},{"id":"muziek","note":"vrolijke muziek"}],"optional":[{"id":"papieren-bordjes","note":"de rand van een bordje als ring om vast te houden"},{"id":"stiften","note":"om het handvat te versieren"},{"id":"kinderschaar","note":"kleuters knippen de stroken zelf"}],"steps":["Knip crêpepapier in stroken van ongeveer 3 cm breed en 50 cm lang, in een paar kleuren.","Plak 3-5 stroken met flinke stukken plakband aan de binnenkant van een wc-rolletje: dat is het handvat.","Versier het handvat eventueel met stiften.","Zet vrolijke muziek op en dans samen: zwaai de linten hoog, laag, in rondjes en in golven.","Speel stopdans: als de muziek stopt, blijft iedereen stokstijf staan en hangen de linten slap naar beneden.","Bewaar de danslinten na afloop op een vaste plek, buiten bereik van het bedje."],"ageTips":{"young":"Een dreumes houdt een dik wc-rolletje of de rand van een papieren bordje makkelijker vast dan een ijsstokje. Dans samen, op de arm of aan de hand, en benoem: omhoog, omlaag, rondje!","old":"Laat je kleuter een eigen dans bedenken en die aan jou leren: eerst drie rondjes, dan een golf… Of teken met het lint een letter of cijfer in de lucht."},"safety":["Wurggevaar: houd de linten kort (±50 cm), nooit om de nek, en ruim ze op voor het slapen. Crêpepapier scheurt makkelijk en is daardoor veiliger dan stevig lint.","Zorg voor ruimte: schuif de salontafel opzij en dans niet op sokken op een gladde vloer.","Crêpepapier geeft kleur af als het nat wordt: laat je dreumes er niet op sabbelen."],"say":["Zwaai, zwaai! Omhoog!","Kun je het lint heel langzaam laten bewegen, als een slang?","Ik zie je lint rondjes draaien boven je hoofd.","Wat doe je goed je best om stil te staan als de muziek stopt!","Welke kleur lint wil jij vandaag?"],"words":["zwaaien","draaien","omhoog","omlaag","rondje","golf","stilstaan"],"learn":["grove-motoriek","creativiteit","concentratie"],"tips":["Knip de dichtgevouwen rol crêpepapier in plakken van 3 cm: zo heb je in één keer een hele bos lange stroken.","Stroken van een oud laken of T-shirt gaan langer mee dan crêpepapier en kunnen gewoon in de was."],"variations":["Koningsdag: maak oranje en rood-wit-blauwe linten en houd een optocht door de kamer.","Carnaval: verkleed je, pak je linten en loop met z’n allen een polonaise door het huis.","Weerdans: dans zachtjes als een briesje en wild als een storm. Wie bedenkt het volgende weer?","Kleurendans: maak een lint in elke kleur; roep een kleur en alleen dat lint mag dansen."],"themes":["koningsdag","carnaval"]},
  {"id":"ballontennis","title":"Ballontennis met bordjesrackets","emoji":"🎈","category":"muziek","summary":"Maak rackets van papieren bordjes en houd samen een ballon in de lucht: een rustig balspel dat binnen prima kan.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"papieren-bordjes","note":"1 per racket, liefst stevige"},{"id":"ijsstokjes","note":"2 per racket, als handvat"},{"id":"ducttape","note":"om de stokjes stevig vast te plakken"},{"id":"ballonnen","note":"niet te hard opgeblazen (door jou)"}],"optional":[{"id":"stiften","note":"om een gezicht op het racket te tekenen"},{"id":"stickers"}],"steps":["Blaas een ballon op, niet te hard, en knoop hem goed dicht. Dat doe jij.","Plak twee ijsstokjes met ducttape tegen de onderkant van een papieren bordje: dat is het handvat.","Laat je kind het racket versieren met een gezichtje of stickers.","Tik de ballon met het racket omhoog. Lukt het om hem in de lucht te houden zonder dat hij de grond raakt?","Speel samen over en weer, of tel hoe vaak het lukt om hem achter elkaar te raken.","Laat na afloop de lucht uit de ballon of berg hem hoog op, en gooi een geknapte ballon meteen weg."],"ageTips":{"young":"Voor een tweejarige gaat een ballon fijn langzaam, maar een racket is nog lastig. Laat je kind eerst met de handen tikken, of houd het racket samen vast.","old":"Tel samen hoe vaak je de ballon hoog kunt houden en probeer je record te verbeteren. Of zet een stoel in het midden als net en speel een echte wedstrijd."},"safety":["Ballonnen alleen onder toezicht: gooi een kapotte ballon of een los stukje meteen weg, want dat is een groot verstikkingsgevaar. Laat een kind onder de 8 nooit zelf een ballon opblazen.","Ruim breekbare spullen en de salontafel opzij: wie naar de ballon kijkt, ziet niet waar hij loopt."],"say":["Tik! Omhoog!","Hoe lang kun je hem in de lucht houden?","Ik zie dat je goed naar de ballon blijft kijken.","Wat denk je: valt een ballon snel of langzaam?","Je bleef het proberen, en nu lukte het al vijf keer achter elkaar!"],"words":["omhoog","tikken","zweven","vallen","langzaam","hooghouden","racket"],"learn":["grove-motoriek","concentratie","samen","rekenen"],"tips":["Een ballon die niet te hard is opgeblazen, knapt minder snel en is fijner om mee te spelen.","Geen papieren bordjes? Een opgerolde krant of gewoon je hand werkt ook."],"variations":["Verjaardag: speel na het feest met de ballonnen van de versiering en houd ze allemaal tegelijk in de lucht.","Zonder racket: houd de ballon hoog met alleen je hoofd, je knie of je elleboog.","Muziekballon: houd de ballon hoog zolang de muziek speelt. Stopt de muziek, dan vang je hem."],"themes":[]},
  {"id":"hindernisbaan","title":"Hindernisbaan door de kamer","emoji":"🤸","category":"muziek","summary":"Bouw met kussens, stoelen en een deken een hindernisbaan door de kamer: kruipen, klimmen, balanceren en mikken in één avontuur.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":1,"materials":[{"id":"dekens","note":"kussens om overheen te klimmen en een deken als tunnel"},{"id":"stoelen","note":"2-3 stuks voor de tunnel"},{"id":"schilderstape","note":"voor een lijn om over te balanceren"},{"id":"wasmand","note":"om in te mikken"},{"id":"bal","note":"of een paar opgerolde sokken"}],"optional":[{"id":"knuffels","note":"om onderweg te redden"},{"id":"dozen","note":"een open doos als tunnel"},{"id":"muziek","note":"voor een swingende baan"}],"steps":["Schuif de salontafel opzij en bouw samen een route: een tunnel van een deken over twee stoelen, een berg van kussens en een tapelijn op de vloer.","Zet aan het eind een wasmand neer, met een bal of een paar opgerolde sokken ernaast.","Doe het eerst zelf voor: kruip door de tunnel, klim over de kussens, loop over de lijn en gooi de bal in de mand.","Laat je kind de baan afleggen. Moedig aan en benoem wat je ziet: door, over, onder, langs.","Verander de baan na een paar rondjes: de kussens verder uit elkaar, de lijn zigzag of de mand verder weg.","Ruim samen op: wie brengt de kussens terug naar de bank?"],"ageTips":{"young":"Voor een dreumes is kruipen door de tunnel en over één kussen al een avontuur. Houd de baan kort en laag, ga zelf aan de andere kant van de tunnel zitten en roep: kiekeboe!","old":"Laat je kleuter zelf de route bedenken en tekenen, en neem de tijd op met de stopwatch van je telefoon. Wie kan het snelst, of juist zo langzaam mogelijk?"},"safety":["Bouw op een zachte ondergrond en houd de baan laag: niet over tafels klimmen of van stoelen springen.","Speel op blote voeten of antislipsokken: op gewone sokken glijdt je kind snel uit.","Zet de stoelen voor de tunnel stevig neer, met de rugleuning tegen de bank of de muur, zodat ze niet kunnen omvallen."],"say":["Door de tunnel… kiekeboe!","Hoe kom je over de kussenberg? Klim je of kruip je?","Ik zie dat je je armen wijd houdt op de lijn. Zo blijf je in evenwicht!","Welke hindernis zullen we er nog bij bouwen?","Wat heb je goed doorgezet: de hele baan tot het eind!"],"words":["door","over","onder","langs","klimmen","kruipen","springen","evenwicht"],"learn":["grove-motoriek","taal","creativiteit"],"tips":["Een hindernisbaan is ideaal op een regendag of als je kind stuiterig is: na een paar rondjes is de ergste energie eruit.","Gebruik schilderstape voor de lijnen op de vloer: dat laat meestal geen lijmresten achter."],"variations":["Dierenbaan: kruip als een poes door de tunnel, spring als een kikker over de kussens en waggel als een pinguïn over de lijn.","Reddingsmissie: verstop knuffels langs de route en breng ze één voor één naar de veilige wasmand.","Sinterklaas: maak een dakenroute van kussens en laat je kind een cadeautje in de schoorsteen (de wasmand) gooien."],"themes":[]},
  {"id":"tapelijnen","title":"Balanceren op tapelijnen","emoji":"👣","category":"muziek","summary":"Plak rechte lijnen, zigzaglijnen en golven van schilderstape op de vloer en balanceer, spring en rijd er samen overheen.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"schilderstape","note":"een rol, liefst in een opvallende kleur"}],"optional":[{"id":"speelgoedautos","note":"om over de lijnen te laten rijden"},{"id":"knuffels","note":"om op je hoofd te balanceren"},{"id":"stiften","note":"om cijfers op de hinkelbaan te schrijven"},{"id":"muziek"}],"steps":["Plak met schilderstape een paar lijnen op de vloer: een rechte lijn, een zigzag, een golf en een grote cirkel.","Loop eerst zelf voor: voetje voor voetje over de rechte lijn, met je armen wijd als een koorddanser.","Laat je kind de lijnen volgen: gewoon lopen, op de tenen, zijwaarts, achteruit of als een dier.","Plak voor oudere kinderen een hinkelbaan met vakken en schrijf er met stift cijfers in.","Laat speelgoedautootjes over de lijnen rijden: de zigzag is een bergweg, de cirkel een rotonde.","Laat de tape een paar dagen liggen voor nieuwe spelletjes en trek hem daarna langzaam los."],"ageTips":{"young":"Een dreumes loopt nog niet netjes op een lijn: houd een handje vast en maak de lijn breder met twee stroken naast elkaar, of laat je kind ernaast kruipen met een autootje.","old":"Laat je kleuter van lijn naar lijn springen, hinkelen op één been of met een knuffel op het hoofd balanceren. Ook leuk: zelf een nieuw parcours bedenken en plakken."},"safety":["Balanceer op blote voeten of antislipsokken: op gewone sokken glijdt je kind op laminaat of tegels snel uit.","Trek losgeraakte stukjes tape meteen weg: een dreumes stopt ze zo in de mond.","Plak geen lijnen over een drempel of vlak bij de trap, en houd ze weg bij scherpe tafelhoeken."],"say":["Voetje, voetje, op de lijn!","Kun je ook achteruit over de lijn lopen?","Ik zie dat je je armen uitsteekt om niet te vallen.","Welke lijn vind je het moeilijkst: de rechte of de zigzag?","Wat blijf je goed proberen, ook als je er even afstapt!"],"words":["rechtdoor","zigzag","golf","rondje","evenwicht","tenen","springen","achteruit"],"learn":["grove-motoriek","concentratie","rekenen"],"tips":["Test de tape eerst op een onopvallend plekje: op de meeste vloeren laat schilderstape geen resten achter, op sommige vloerkleden wel.","Plak de lijnen in de gang: daar kom je toch langs, en de woonkamer blijft vrij."],"variations":["Letterpad: plak een grote letter, bijvoorbeeld de eerste letter van de naam van je kind, en loop hem samen na.","Muzieklijnen: zet muziek op en beweeg langs de lijnen, snel als de muziek snel is en langzaam als hij langzaam is.","Autostad: plak een hele stad met wegen, een rotonde en een parkeergarage onder de tafel."],"themes":[]},
  {"id":"fruitgezichtjes","title":"Fruitgezichtjes en fruitdieren","emoji":"🍓","category":"eetbaar","summary":"Leg samen grappige gezichten en dieren van stukjes fruit en groente op een bord, en eet je kunstwerk daarna lekker op.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"fruit","note":"bijv. banaan, appel, mandarijn, kiwi en bessen"},{"id":"groente","note":"bijv. komkommer, paprika en cherrytomaatjes"},{"id":"bord","note":"een groot bord als ‘gezicht’"},{"id":"mes","note":"voor jou, om alles in stukjes te snijden"}],"optional":[{"id":"brood","note":"een cracker of rijstwafel als ondergrond"},{"id":"beleg","note":"roomkaas als lijm op de cracker"},{"id":"kaas","note":"geraspte kaas als haar"},{"id":"muffinvorm","note":"om de stukjes per soort in te doen"}],"steps":["Snijd fruit en groente in kleine stukjes en zet ze per soort in kommetjes klaar. Druiven en cherrytomaatjes snijd je in de lengte in vieren.","Leg een groot bord of een cracker voor je kind neer: dat wordt het gezicht.","Bedenk samen wat de ogen, de neus en de mond worden. Laat je kind zelf kiezen en leggen.","Maak er haar, oren of een hoed bij, bijvoorbeeld van reepjes paprika of een plakje appel.","Bewonder het gezicht, geef het een naam en… smakelijk eten!"],"ageTips":{"young":"Snijd voor een dreumes alles in kleine, zachte stukjes en leg zelf alvast een rond gezicht van plakjes komkommer neer. Laat je kind er ogen op leggen en benoem: oog, neus, mond… hap!","old":"Laat je kleuter een heel dier of een fruittuin leggen, met een verhaal erbij. Of maak een patroon: banaan, aardbei, banaan… wat komt er hierna?"},"safety":["Snijd druiven en cherrytomaatjes in de lengte in vieren, en geef dreumesen geen harde stukjes rauwe appel of wortel: rasp ze of snijd ze in dunne plakjes.","Laat je kind rechtop aan tafel zitten tijdens het eten en niet rondlopen met eten in de mond: zo verslikt het zich minder snel.","Allergie? Let op met kiwi en aardbei bij gevoelige kinderen, en met roomkaas (melk) of crackers (gluten)."],"say":["Wat wordt dit? Een oog of een neus?","Ik zie twee aardbei-ogen en een mond van banaan. Wat een vrolijk gezicht!","Ruik eens aan de mandarijn. Ruikt hij zoet of fris?","Hap! Daar gaat de neus!","Wat een goed idee om paprika als haar te gebruiken."],"words":["oog","neus","mond","rond","zoet","zuur","sappig","haar"],"learn":["creativiteit","fijne-motoriek","taal","zintuigen"],"tips":["Gebruik het fruit dat al in huis is: als ontbijt of tussendoortje eten kinderen zo vaak meer fruit en groente.","Zet de stukjes in een muffinvorm, elk vakje een soort: overzichtelijk en makkelijk pakken."],"variations":["Fruitrups: leg plakjes banaan en kiwi om en om op een rij, met een aardbei als kop.","Koningsdag: maak een oranje gezicht van mandarijn, wortel en meloen.","Halloween: maak bananenspookjes met oogjes van bessen, of een pompoengezicht van partjes mandarijn.","Regenboogbord: leg het fruit op kleur in een boog: rood, oranje, geel, groen en blauw."],"themes":[]},
  {"id":"koekjes-versieren","title":"Koekjes versieren","emoji":"🍪","category":"eetbaar","summary":"Smeer gekleurd glazuur op koekjes en strooi er spikkels over: smeren, strooien en snoepen in één.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"koekjes","note":"biscuitjes of zelfgebakken koekjes, ±15 stuks"},{"id":"poedersuiker","note":"±100 g"},{"id":"water","note":"±1 el, plus een paar druppels"},{"id":"kleurstof","note":"2-3 kleuren"},{"id":"hagelslag","note":"of spikkels"},{"id":"kom","note":"een kommetje per kleur glazuur"},{"id":"lepel","note":"theelepels om te roeren en te smeren"}],"optional":[{"id":"dienblad","note":"om op te werken: gevallen spikkels schud je zo terug"},{"id":"zip-zakjes","note":"als spuitzakje, met een piepklein puntje eraf"},{"id":"bakpapier","note":"om de koekjes op te laten drogen"},{"id":"oud-shirt"}],"steps":["Roer 100 g poedersuiker met 1 el water in een kom. Voeg druppel voor druppel meer water toe tot het glazuur dik is als tandpasta.","Verdeel het glazuur over een paar kommetjes en laat je kind in elk kommetje een druppel kleurstof roeren.","Zet de spikkels en hagelslag in schaaltjes klaar en leg de koekjes op een dienblad.","Laat je kind met de bolle kant van een theelepel glazuur op een koekje smeren en er meteen spikkels over strooien.","Leg de versierde koekjes op bakpapier en laat ze ongeveer een uur drogen. Eentje meteen opeten mag natuurlijk ook.","Bewaar de droge koekjes in een trommel; ze blijven een paar dagen lekker."],"ageTips":{"young":"Een tweejarige strooit vooral, en dat mag. Smeer zelf alvast wat glazuur op een paar koekjes en geef een klein bakje spikkels: een deel gaat in de mond, en dat is prima.","old":"Laat je kleuter vooraf een ontwerp bedenken: een gezichtje, een patroon of een letter. Met een diepvrieszakje met een piepklein puntje eraf spuit je echte lijntjes."},"safety":["Allergie: koekjes bevatten vaak gluten, melk en ei, en spikkels soms sporen van noten. Lees de verpakking als er een kind met een allergie meedoet.","Kleurstof vlekt op kleding en tafel: trek een oud shirt aan en werk op een dienblad of afwasbaar tafelkleed.","Gebruik voor kinderen onder de 3 gewone hagelslag en geen harde suikerparels: die zijn klein en hard."],"say":["Strooi, strooi! Kijk eens hoeveel spikkels!","Hoe voelt het glazuur: dik of dun? Plakkerig?","Ik zie dat je eerst roze hebt gesmeerd en daarna gele spikkels. Wat een vrolijk koekje.","Voor wie maak je dit koekje?","Wat werk je geduldig: helemaal tot aan de randjes."],"words":["smeren","strooien","zoet","plakkerig","spikkels","glazuur","dik","dun"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Maak het glazuur liever te dik dan te dun: dun glazuur loopt van het koekje af. Een extra tl poedersuiker maakt het weer dikker.","Werk op een dienblad met een rand: spikkels die ernaast vallen, schud je zo terug in het bakje."],"variations":["Sinterklaas: versier speculaasjes of letterkoekjes met de eerste letter van ieders naam.","Kerst: smeer groen glazuur op stervormige koekjes en strooi er gekleurde spikkels op als kerstballen.","Verjaardag: versier samen traktatiekoekjes met de leeftijd van de jarige erop.","Gezichtjes: maak elkaar na op een koekje. Wie is wie?"],"themes":["sinterklaas","kerst","verjaardag"]},
  {"id":"kruidnoten-bakken","title":"Kruidnoten bakken","emoji":"🥣","category":"eetbaar","summary":"Kneed samen een geurig deeg met speculaaskruiden, rol knikkergrote balletjes en bak je eigen kruidnoten voor Sinterklaas.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":30,"supervision":1,"materials":[{"id":"zelfrijzend-bakmeel","note":"125 g"},{"id":"basterdsuiker","note":"60 g"},{"id":"boter","note":"50 g, zacht (op kamertemperatuur)"},{"id":"melk","note":"2-3 el"},{"id":"kruiden","note":"1-2 tl speculaaskruiden"},{"id":"zout","note":"een snufje"},{"id":"kom","note":"een grote mengkom"},{"id":"bakpapier","note":"voor op de bakplaat"},{"id":"oven","note":"180 °C; de oven is voor jou"}],"optional":[{"id":"oud-shirt","note":"of een schort"},{"id":"zip-zakjes","note":"om kruidnoten in uit te delen"}],"steps":["Zet de oven aan op 180 °C en leg bakpapier op de bakplaat. Dat doe jij.","Weeg samen af: 125 g zelfrijzend bakmeel, 60 g basterdsuiker, 1-2 tl speculaaskruiden en een snufje zout. Laat je kind alles in de kom schudden.","Doe er 50 g zachte boter en 2 el melk bij en kneed met je handen tot een soepel deeg. Te droog? Nog een scheutje melk erbij.","Rol samen knikkergrote balletjes en leg ze met wat ruimte ertussen op de bakplaat. Tel maar mee!","Schuif de bakplaat in de oven (dat doe jij) en bak de kruidnoten ±15 minuten, tot ze goudbruin zijn.","Laat ze afkoelen op de bakplaat: dan worden ze knapperig. Bewaar ze in een trommel of pot."],"ageTips":{"young":"Weeg voor een tweejarige alles vooraf af in bakjes: dan hoeft je peuter alleen te gooien, kneden en rollen. Halveer het recept voor een kleine, overzichtelijke portie; scheve balletjes zijn net zo lekker.","old":"Laat je kleuter zelf afwegen en de cijfers op de weegschaal aflezen. Leg de balletjes in rijtjes van tien en tel samen hoeveel kruidnoten het worden."},"safety":["De oven en de hete bakplaat zijn voor jou: laat je kind op afstand blijven als de ovendeur opengaat.","Niet van het rauwe deeg snoepen: rauwe bloem kan bacteriën bevatten.","Kruidnoten zijn klein, rond en hard: breek ze voor jonge kinderen doormidden en laat ze aan tafel zittend eten.","Allergie: dit recept bevat gluten en melk. Gebruik bij een melkallergie plantaardige boter en plantaardige melk."],"say":["Rollen, rollen… een balletje!","Ruik eens aan de speculaaskruiden. Waar doet dat je aan denken?","Hoe voelt het deeg: plakkerig, droog of zacht?","Ik zie een hele rij balletjes. Zullen we tellen hoeveel het er zijn?","Wat heb je goed geholpen: jij hebt alles zelf in de kom gedaan."],"words":["afwegen","kneden","rollen","balletje","ruiken","knapperig","warm","afkoelen"],"learn":["fijne-motoriek","rekenen","zintuigen","samen"],"tips":["Weeg alles af voordat je je kind erbij roept: dan blijft het leukste werk over en hoeft er niet lang gewacht te worden.","Plakt het deeg aan de handjes? Een beetje bakmeel op de handen helpt.","In een goed gesloten trommel of pot blijven kruidnoten een paar weken lekker."],"variations":["Traktatie: doe een handje kruidnoten in een zakje met een strik en geef ze aan opa, oma of de buren.","Chocoladekruidnoten: doop de afgekoelde kruidnoten half in gesmolten chocolade. Het smelten doe jij.","Vormpjes: rol het deeg uit en steek er kleine sterretjes of letters uit. Bak ze iets korter, ±10 minuten."],"themes":["sinterklaas"]},
  {"id":"boterhamkunst","title":"Boterhamkunst met vormpjes","emoji":"🍞","category":"eetbaar","summary":"Steek vormpjes uit een boterham, gebruik beleg als lijm en versier je brood met gezichtjes van fruit, groente en hagelslag.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"brood","note":"een paar boterhammen of wraps"},{"id":"uitsteekvormpjes","note":"liefst grote, simpele vormen (hart, ster, rondje)"},{"id":"beleg","note":"roomkaas, smeerkaas of jam als ‘lijm’"},{"id":"fruit","note":"in kleine stukjes, bijv. banaan en bessen"},{"id":"groente","note":"bijv. reepjes komkommer, paprika en wortel"},{"id":"hagelslag","note":"voor haar of spikkels"},{"id":"mes","note":"voor jou om te snijden; je kind smeert met een botermes"}],"optional":[{"id":"deegroller","note":"om het brood eerst plat te rollen"},{"id":"kaas","note":"geraspte kaas als haar"}],"steps":["Snijd groente en fruit in kleine stukjes en zet alles in kommetjes klaar: dat is je ‘verfdoos’.","Laat je kind een vormpje kiezen en uit een boterham steken: stevig drukken en een beetje heen en weer wiebelen.","Smeer samen een laagje roomkaas of jam op de vorm; dat is de lijm.","Versier de boterham met ogen van bessen, een mond van paprika en haar van hagelslag of kaas.","Bekijk het kunstwerk samen, bedenk een naam en… opeten!"],"ageTips":{"young":"Voor een tweejarige is uitsteken nog lastig: druk het vormpje samen in het brood, of steek zelf alvast een paar vormen uit. Smeren gaat makkelijker met de bolle kant van een lepel.","old":"Laat je kleuter een heel tafereel op een bord maken: een huis van brood, een zon van kaas en bloemen van komkommer. Of leg samen de eerste letter van de eigen naam met reepjes groente."},"safety":["Allergie: brood bevat gluten, roomkaas melk en sommige smeersels noten of pinda. Kies beleg dat past bij alle kinderen aan tafel.","Snijd druiven en cherrytomaatjes in de lengte in vieren, en harde groente zoals wortel voor jonge kinderen in dunne reepjes of geraspt.","Metalen uitsteekvormpjes hebben één scherpe kant: laat je kind op de omgerolde bovenrand drukken."],"say":["Druk, druk… en eruit! Een hartje!","Wat wordt dit, denk je? Een poes of een monster?","Ik zie dat je de bessen heel precies als oogjes hebt neergelegd.","Hoe smaakt de komkommer: fris of zoet?","Smeer, smeer, tot aan de randjes!"],"words":["uitsteken","smeren","hartje","ster","rondje","bovenop","plakkerig"],"learn":["fijne-motoriek","creativiteit","rekenen","taal"],"tips":["Rol de boterham eerst plat met een deegroller: dan gaat uitsteken veel makkelijker en blijft de vorm heel.","Gooi de randjes niet weg: maak er tosti’s, wentelteefjes of broodkruim van."],"variations":["Sinterklaas: snijd of steek een letter uit en strooi er hagelslag over: een chocoladeletter van brood.","Kerst: steek boompjes of sterren uit en versier ze met reepjes paprika als slingers.","Verjaardag: stapel drie rondjes brood met beleg ertussen tot een boterhamtaart en zet er een rietje als kaarsje in."],"themes":[]},
  {"id":"fruitijsjes","title":"Fruitijsjes maken","emoji":"🍦","category":"eetbaar","summary":"Prak fruit met yoghurt, schep het in vormpjes en vries het in: zelfgemaakte ijsjes waarbij je kind proeft, ruikt en kleuren ontdekt.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"fruit","note":"±250 g zacht fruit, bijv. aardbeien, banaan, mango of bessen"},{"id":"yoghurt","note":"±250 g, bijv. Griekse yoghurt"},{"id":"ijsvormpjes","note":"of bekertjes met een ijsstokje erin"},{"id":"vork","note":"om te prakken"},{"id":"kom","note":"om in te prakken en te roeren"},{"id":"vriezer"}],"optional":[{"id":"blender","note":"voor een gladder ijsje"},{"id":"ijsblokjesvorm","note":"voor mini-ijsjes voor een dreumes"},{"id":"huishoudfolie","note":"over de bekertjes, zodat het stokje rechtop blijft"},{"id":"ijsstokjes","note":"als je met bekertjes werkt"}],"steps":["Was het fruit en snijd het in stukjes. Laat je kind de zachte stukjes, zoals banaan en aardbei, met een vork fijnprakken in een kom.","Roer er ongeveer evenveel yoghurt door. Wil je het heel glad, pureer het dan met de blender; dat doe jij.","Proef samen een likje: zoet genoeg? Een extra stukje rijpe banaan maakt het zoeter, zonder suiker.","Schep het mengsel in de ijsvormpjes en zet de stokjes erin. Morsen mag, aflikken ook!","Zet de vormpjes minstens 4 uur in de vriezer, of een nacht.","Houd een vormpje even onder de warme kraan: dan glijdt het ijsje er zo uit."],"ageTips":{"young":"Voor een dreumes is een ijsje op een stokje vaak te groot en te koud. Vries het mengsel in een ijsblokjesvorm in en geef één blokje in een kommetje. Prakken met de handen mag ook!","old":"Laat je kleuter een eigen recept bedenken en tekenen: welk fruit, hoeveel lepels yoghurt? Na het invriezen proef je samen of het recept geslaagd is."},"safety":["Allergie: yoghurt bevat melk. Gebruik bij een melkallergie alleen fruit of een plantaardige yoghurt.","Prak of pureer alles goed voor een dreumes: hele bessen of harde stukjes in het ijs kunnen in de keel schieten.","Een ijsje dat net uit de vriezer komt, kan aan lippen of tong vastvriezen: laat het eerst een minuutje liggen."],"say":["Prak, prak! Kijk, de banaan wordt zacht.","Welke kleur krijgt het als we de aardbeien erbij doen?","Ruik eens: ruikt het naar aardbei of naar banaan?","Wat denk je dat er in de vriezer gebeurt?","Brr, koud! Hoe voelt het op je tong?"],"words":["prakken","zacht","koud","bevroren","smelten","zoet","zuur","roze"],"learn":["zintuigen","fijne-motoriek","taal","ontdekken"],"tips":["Overrijp fruit of een zak diepvriesfruit is goedkoop en perfect voor ijsjes.","Geen ijsvormpjes? Gebruik plastic bekertjes, span er huishoudfolie over en prik het stokje erdoor: dan blijft het rechtop staan.","Laat je kind het ijsje aan tafel eten met een slabbetje of oud shirt aan: smeltend fruitijs druppelt en vlekt."],"variations":["Streepjesijs: vul de vormpjes laag voor laag met verschillende kleuren en vries elke laag een uurtje aan.","Sapijsjes: vries puur appelsap of geperst sinaasappelsap in, lekker verkoelend op een warme dag.","Koningsdag: maak oranje ijsjes van mango, sinaasappel en een beetje wortelsap.","Monsterijsjes: pureer banaan met een handje verse spinazie: knalgroen, en je proeft het bijna niet."],"themes":["zomer"]},
  {"id":"minipizzas","title":"Mini-pizza’s beleggen","emoji":"🍕","category":"eetbaar","summary":"Smeer saus op een wrap of pitabroodje, strooi kaas en leg een gezichtje van groente: zelfgemaakte pizza’s die je kind trots opeet.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"brood","note":"kleine wraps, pitabroodjes of halve bolletjes"},{"id":"tomatensaus","note":"±1 el per pizza"},{"id":"kaas","note":"geraspt"},{"id":"groente","note":"bijv. paprika, champignons, maïs en cherrytomaatjes"},{"id":"bakpapier","note":"voor op de bakplaat"},{"id":"oven","note":"200 °C; de oven is voor jou"},{"id":"lepel","note":"om de saus te smeren"}],"optional":[{"id":"uitsteekvormpjes","note":"om sterretjes uit plakjes paprika of kaas te steken"},{"id":"oud-shirt","note":"tomatensaus vlekt"}],"steps":["Verwarm de oven voor op 200 °C en leg bakpapier op de bakplaat. Dat doe jij.","Snijd de groente in kleine stukjes en zet alles met de kaas in kommetjes klaar. Cherrytomaatjes snijd je in vieren.","Leg voor je kind een wrap of pitabroodje neer en laat het met de bolle kant van een lepel tomatensaus uitsmeren.","Laat je kind de pizza beleggen: kaas strooien en een gezichtje, bloem of patroon leggen met de groente.","Schuif de pizza’s in de oven en bak ze 8-10 minuten, tot de kaas gesmolten is. Kijk samen door het ovenraampje.","Laat de pizza’s een paar minuten afkoelen voordat je ze in stukken snijdt: gesmolten kaas is heet."],"ageTips":{"young":"Een tweejarige strooit vooral kaas, en heel veel. Geef kleine bakjes met grote, zachte stukjes groente en laat het patroon los: elke pizza is goed.","old":"Laat je kleuter een pizza bedenken voor iemand anders in huis: wat vindt die lekker? Of verdeel de pizza in vier vakken met elk een ander beleg en tel de stukjes."},"safety":["De oven, de hete bakplaat en gesmolten kaas zijn heet: haal de pizza’s er zelf uit en laat ze eerst afkoelen.","Allergie: wraps en pitabroodjes bevatten gluten, kaas bevat melk. Er zijn glutenvrije wraps en kaas zonder melk.","Snijd cherrytomaatjes in de lengte in vieren: heel zijn ze een verstikkingsgevaar."],"say":["Smeer, smeer! Helemaal tot de rand.","Wat leg jij op je pizza? Wat worden de ogen?","Ruik je dat? De kaas smelt in de oven.","Kijk door het raampje: wat gebeurt er met de kaas?","Je hebt je pizza helemaal zelf belegd. Hoe gaat hij heten?"],"words":["smeren","strooien","smelten","heet","rond","kaas","plakjes"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Gebruik restjes uit de koelkast, zoals een halve paprika of een stukje kaas: zo is het meteen een avondmaaltijd.","Trek je kind een oud shirt aan: tomatensaus vlekt, en kleine handen smeren graag met hun vingers."],"variations":["Halloween: maak een mummiepizza met reepjes kaas als verband en twee plakjes paprika als ogen.","Koningsdag: beleg de pizza met alles wat oranje is, zoals oranje paprika, geraspte wortel en cheddar.","Fruitpizza: smeer roomkaas op een cracker en beleg die met fruit; die hoeft niet eens de oven in."],"themes":[]},
];
